{
  "name": "herdr-discord-bot",
  "version": "0.1.0",
  "private": true,
  "description": "Control herdr agents from Discord (owner-locked ChatOps bridge)",
  "main": "src/index.js",
  "scripts": {
    "start": "node src/index.js",
    "deploy": "node src/deploy-commands.js",
    "test": "node --test"
  },
  "dependencies": {
    "discord.js": "^14.16.3",
    "dotenv": "^16.4.5"
  },
  "engines": {
    "node": ">=18"
  }
}

// browser.js — drive a throwaway headless Chromium over CDP to test local apps.
//
// Deliberately does NOT touch the user's real browser profile: every run gets a
// fresh --user-data-dir under the system temp dir, and the browser is killed
// afterwards. Uses only `ws`, which discord.js already depends on, so there is
// no puppeteer/playwright requirement.

const { spawn, execFile } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const net = require('node:net');
const WebSocket = require('ws');

const CANDIDATES = [
  process.env.BROWSER_BIN,
  'brave-browser-nightly',
  'brave-browser',
  'chromium',
  'chromium-browser',
  'google-chrome',
].filter(Boolean);

function which(bin) {
  return new Promise((resolve) => {
    execFile('which', [bin], (err, stdout) => resolve(err ? null : stdout.trim()));
  });
}

async function findBrowser() {
  for (const c of CANDIDATES) {
    if (c.startsWith('/') && fs.existsSync(c)) return c;
    const p = await which(c);
    if (p) return p;
  }
  return null;
}

function freePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, '127.0.0.1', () => {
      const { port } = srv.address();
      srv.close(() => resolve(port));
    });
    srv.on('error', reject);
  });
}

async function waitForEndpoint(port, timeoutMs = 15000) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/version`);
      if (res.ok) return await res.json();
    } catch {
      /* not up yet */
    }
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error('browser did not expose a debugging endpoint in time');
}

// Minimal CDP client: one websocket, request/response by id, plus event taps.
class CDP {
  constructor(url) {
    this.url = url;
    this.id = 0;
    this.pending = new Map();
    this.events = [];
  }
  connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.url, { perMessageDeflate: false });
      this.ws.on('open', () => resolve(this));
      this.ws.on('error', reject);
      this.ws.on('message', (raw) => {
        let msg;
        try {
          msg = JSON.parse(raw);
        } catch {
          return;
        }
        if (msg.id && this.pending.has(msg.id)) {
          const { resolve: res, reject: rej } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          msg.error ? rej(new Error(msg.error.message)) : res(msg.result);
        } else if (msg.method) {
          this.events.push(msg);
        }
      });
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => {
        if (this.pending.has(id)) {
          this.pending.delete(id);
          reject(new Error(`${method} timed out`));
        }
      }, 30000);
    });
  }
  close() {
    try {
      this.ws?.close();
    } catch {
      /* already gone */
    }
  }
}

// Launch headless, run `fn(cdp)`, then always tear the browser down.
async function withBrowser(fn, { headless = true } = {}) {
  const bin = await findBrowser();
  if (!bin) throw new Error('no Chromium-family browser found on this machine');

  const port = await freePort();
  const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'herdrbot-browser-'));
  const args = [
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${profile}`,
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-background-networking',
    '--disable-extensions',
    '--window-size=1280,900',
  ];
  if (headless) args.push('--headless=new', '--disable-gpu');

  const proc = spawn(bin, args, { stdio: 'ignore', detached: false });
  let cdp = null;
  try {
    await waitForEndpoint(port);
    const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    let page = targets.find((t) => t.type === 'page');
    if (!page) {
      const created = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, {
        method: 'PUT',
      });
      page = await created.json();
    }
    cdp = await new CDP(page.webSocketDebuggerUrl).connect();
    return await fn(cdp);
  } finally {
    cdp?.close();
    try {
      proc.kill('SIGTERM');
    } catch {
      /* already exited */
    }
    setTimeout(() => {
      try {
        proc.kill('SIGKILL');
      } catch {
        /* gone */
      }
      fs.rm(profile, { recursive: true, force: true }, () => {});
    }, 1500);
  }
}

// Screenshot a URL, collecting console errors and failed requests along the way
// — a blank page with a stack trace is far more useful than a blank page.
async function capture(url, { fullPage = true, waitMs = 1200 } = {}) {
  return withBrowser(async (cdp) => {
    await cdp.send('Page.enable');
    await cdp.send('Runtime.enable');
    await cdp.send('Log.enable').catch(() => {});
    await cdp.send('Network.enable').catch(() => {});

    const started = Date.now();
    await cdp.send('Page.navigate', { url });

    // Wait for load, but never hang forever on a slow or broken page.
    await new Promise((resolve) => {
      const done = () => resolve();
      const timer = setTimeout(done, 12000);
      const poll = setInterval(() => {
        if (cdp.events.some((e) => e.method === 'Page.loadEventFired')) {
          clearInterval(poll);
          clearTimeout(timer);
          done();
        }
      }, 100);
    });
    await new Promise((r) => setTimeout(r, waitMs)); // let the app paint

    const title = await cdp
      .send('Runtime.evaluate', { expression: 'document.title', returnByValue: true })
      .then((r) => r.result?.value)
      .catch(() => null);

    const shot = await cdp.send('Page.captureScreenshot', {
      format: 'png',
      captureBeyondViewport: fullPage,
    });

    const consoleErrors = cdp.events
      .filter((e) => e.method === 'Log.entryAdded' && e.params?.entry?.level === 'error')
      .map((e) => e.params.entry.text)
      .slice(0, 10);
    const failed = cdp.events
      .filter((e) => e.method === 'Network.loadingFailed')
      .map((e) => e.params?.errorText)
      .filter(Boolean)
      .slice(0, 10);

    return {
      url,
      title,
      png: Buffer.from(shot.data, 'base64'),
      ms: Date.now() - started,
      consoleErrors,
      failedRequests: failed,
    };
  });
}

// --- driving a page, not just photographing it ------------------------------
//
// A step is one verb and its argument, written the way you would say it:
//
//   goto <url>            navigate mid-flow
//   click <text|css>      visible text first, CSS selector as a fallback
//   type <css> <text>     focus that field and type (selector = first token)
//   wait <ms|text>        a number sleeps; anything else waits for that text
//   expect <text>         fail the step unless the page shows it
//
// Steps run in order and stop at the first failure, because every later step
// was written assuming the earlier ones worked.

const STEP_TIMEOUT_MS = 10000;

function parseSteps(text) {
  return String(text || '')
    .split(/\s*;\s*/)
    .map((s) => s.trim())
    .filter(Boolean)
    .map((raw) => {
      const m = raw.match(/^(\w+)\s*(.*)$/s);
      return { raw, verb: (m?.[1] || '').toLowerCase(), arg: (m?.[2] || '').trim() };
    });
}

// Serialised into the page: find by visible text, then by CSS. Text wins
// because that is how a person describes a button they can see.
const FIND_FN = `function(needle){
  var all = Array.from(document.querySelectorAll('button,a,[role="button"],input,textarea,select,label,summary'));
  var hit = all.find(function(el){
    var t = (el.innerText || el.value || el.getAttribute('aria-label') || '').trim();
    return t && t.toLowerCase().indexOf(needle.toLowerCase()) >= 0;
  });
  if(!hit){ try { hit = document.querySelector(needle); } catch(e) { hit = null; } }
  if(!hit) return null;
  hit.scrollIntoView({block:'center'});
  var r = hit.getBoundingClientRect();
  return {x: r.left + r.width/2, y: r.top + r.height/2, tag: hit.tagName.toLowerCase(),
          label: (hit.innerText || hit.value || '').trim().slice(0,40)};
}`;

async function pageText(cdp) {
  const r = await cdp
    .send('Runtime.evaluate', {
      expression: 'document.body ? document.body.innerText : ""',
      returnByValue: true,
    })
    .catch(() => null);
  return r?.result?.value || '';
}

async function runStep(cdp, { verb, arg }) {
  if (verb === 'goto') {
    await cdp.send('Page.navigate', { url: arg });
    await new Promise((r) => setTimeout(r, 1500));
    return `at ${arg}`;
  }

  if (verb === 'wait') {
    const ms = Number(arg);
    if (Number.isFinite(ms) && ms > 0) {
      await new Promise((r) => setTimeout(r, Math.min(ms, STEP_TIMEOUT_MS)));
      return `waited ${ms}ms`;
    }
    const deadline = Date.now() + STEP_TIMEOUT_MS;
    while (Date.now() < deadline) {
      if ((await pageText(cdp)).toLowerCase().includes(arg.toLowerCase())) return `saw "${arg}"`;
      await new Promise((r) => setTimeout(r, 250));
    }
    throw new Error(`"${arg}" never appeared`);
  }

  if (verb === 'expect') {
    const text = await pageText(cdp);
    if (!text.toLowerCase().includes(arg.toLowerCase())) {
      throw new Error(`page does not show "${arg}"`);
    }
    return `found "${arg}"`;
  }

  if (verb === 'click') {
    const found = await cdp
      .send('Runtime.evaluate', {
        expression: `(${FIND_FN})(${JSON.stringify(arg)})`,
        returnByValue: true,
      })
      .then((r) => r.result?.value);
    if (!found) throw new Error(`nothing matching "${arg}"`);
    for (const type of ['mousePressed', 'mouseReleased']) {
      await cdp.send('Input.dispatchMouseEvent', {
        type,
        x: found.x,
        y: found.y,
        button: 'left',
        clickCount: 1,
      });
    }
    await new Promise((r) => setTimeout(r, 600));
    return `clicked ${found.tag}${found.label ? ` "${found.label}"` : ''}`;
  }

  if (verb === 'type') {
    const [selector, ...rest] = arg.split(/\s+/);
    const value = rest.join(' ');
    const ok = await cdp
      .send('Runtime.evaluate', {
        expression: `(function(){
          var el = null;
          try { el = document.querySelector(${JSON.stringify(selector)}); } catch(e) {}
          if(!el) return false;
          el.scrollIntoView({block:'center'});
          el.focus();
          return true;
        })()`,
        returnByValue: true,
      })
      .then((r) => r.result?.value);
    if (!ok) throw new Error(`no field matching "${selector}"`);
    // insertText goes through the same path as a real keystroke, so framework
    // inputs see the change; setting .value directly would not fire anything.
    await cdp.send('Input.insertText', { text: value });
    await new Promise((r) => setTimeout(r, 300));
    return `typed into ${selector}`;
  }

  throw new Error(`unknown step "${verb}"`);
}

// Walk a URL through a list of steps and report what each one did.
async function drive(url, stepText, { waitMs = 1500 } = {}) {
  const steps = parseSteps(stepText);
  if (!steps.length) throw new Error('no steps to run');

  return withBrowser(async (cdp) => {
    await cdp.send('Page.enable');
    await cdp.send('Runtime.enable');
    await cdp.send('Log.enable').catch(() => {});
    await cdp.send('Network.enable').catch(() => {});

    const started = Date.now();
    await cdp.send('Page.navigate', { url });
    await new Promise((r) => setTimeout(r, waitMs));

    const results = [];
    for (const step of steps) {
      const at = Date.now();
      try {
        const detail = await runStep(cdp, step);
        results.push({ raw: step.raw, ok: true, detail, ms: Date.now() - at });
      } catch (e) {
        results.push({ raw: step.raw, ok: false, detail: e.message, ms: Date.now() - at });
        break; // later steps assumed this one worked
      }
    }

    const title = await cdp
      .send('Runtime.evaluate', { expression: 'document.title', returnByValue: true })
      .then((r) => r.result?.value)
      .catch(() => null);
    const shot = await cdp.send('Page.captureScreenshot', { format: 'png' });

    return {
      url,
      title,
      ok: results.every((r) => r.ok),
      steps: results,
      png: Buffer.from(shot.data, 'base64'),
      ms: Date.now() - started,
      consoleErrors: cdp.events
        .filter((e) => e.method === 'Log.entryAdded' && e.params?.entry?.level === 'error')
        .map((e) => e.params.entry.text)
        .slice(0, 10),
      failedRequests: cdp.events
        .filter((e) => e.method === 'Network.loadingFailed')
        .map((e) => e.params?.errorText)
        .filter(Boolean)
        .slice(0, 10),
    };
  });
}

// Which local ports are actually serving HTTP right now.
function listeningPorts() {
  return new Promise((resolve) => {
    execFile('ss', ['-ltnp'], (err, stdout) => {
      if (err) return resolve([]);
      const ports = new Set();
      for (const line of stdout.split('\n').slice(1)) {
        const m = line.match(/127\.0\.0\.1:(\d+)|0\.0\.0\.0:(\d+)|\*:(\d+)/);
        if (m) {
          const p = Number(m[1] || m[2] || m[3]);
          if (p && p > 1024) ports.add(p);
        }
      }
      resolve([...ports].sort((a, b) => a - b));
    });
  });
}

module.exports = { capture, drive, parseSteps, withBrowser, findBrowser, listeningPorts, CDP };

// ci-watch.js — push GitHub CI results into each project's channel.
//
// gh has no event stream, so this polls. It is deliberately quiet: a run is
// announced once, and only when it finishes. Successes are announced only if
// they follow a failure (a green run after red is news; the twentieth green in
// a row is not).

const gh = require('./github');

const POLL_MS = Number(process.env.CI_POLL_MS || 180000); // 3 min

class CIWatch {
  constructor({ sync, store, log = console }) {
    this.sync = sync;
    this.store = store;
    this.log = log;
    this.timer = null;
    this.seen = new Map(); // repo -> last announced run id
    this.lastState = new Map(); // repo -> 'success' | 'failure'
    this.repoFor = new Map(); // projectKey -> repo slug (or null)
  }

  async start() {
    if (!(await gh.isAvailable())) {
      this.log.info?.('[ci] gh is not authenticated — CI watch disabled');
      return false;
    }
    const persisted = this.store?.getMeta?.('ciSeen') || {};
    for (const [k, v] of Object.entries(persisted)) this.seen.set(k, v);
    const states = this.store?.getMeta?.('ciState') || {};
    for (const [k, v] of Object.entries(states)) this.lastState.set(k, v);

    await this.poll().catch((e) => this.log.error('[ci] first poll failed:', e.message));
    this.timer = setInterval(() => {
      this.poll().catch((e) => this.log.error('[ci] poll failed:', e.message));
    }, POLL_MS);
    this.log.info?.(`[ci] watching (every ${Math.round(POLL_MS / 1000)}s)`);
    return true;
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  async poll() {
    if (!this.sync?.channels?.size) return;

    for (const [projectKey, channelId] of this.sync.channels) {
      let repo = this.repoFor.get(projectKey);
      if (repo === undefined) {
        repo = await gh.repoForDir(projectKey).catch(() => null);
        this.repoFor.set(projectKey, repo);
      }
      if (!repo) continue;

      let runs;
      try {
        runs = await gh.listRuns(repo, { limit: 5 });
      } catch {
        continue; // a repo we cannot read is not worth retrying loudly
      }
      const latest = runs.find((r) => r.status === 'completed');
      if (!latest) continue;

      const already = this.seen.get(repo);
      if (already === latest.id) continue; // nothing new since last time
      const previous = this.lastState.get(repo);
      this.seen.set(repo, latest.id);
      this.lastState.set(repo, latest.conclusion);
      this.store?.setMeta?.('ciSeen', Object.fromEntries(this.seen));
      this.store?.setMeta?.('ciState', Object.fromEntries(this.lastState));

      // First sighting of a repo just establishes a baseline — announcing it
      // would spam every channel on the first boot.
      if (already === undefined) continue;

      const failed = latest.conclusion === 'failure';
      const recovered = !failed && previous === 'failure';
      if (!failed && !recovered) continue;

      const channel = await this.sync.guild?.channels.fetch(channelId).catch(() => null);
      if (!channel) continue;

      await channel
        .send({
          content:
            (failed
              ? `❌ **CI failed** on \`${latest.branch}\``
              : `✅ **CI recovered** on \`${latest.branch}\``) +
            `\n${gh.runLine(latest)}`,
          allowedMentions: { parse: [] },
        })
        .catch((e) => this.log.error('[ci] send failed:', e.message));
      this.log.info?.(`[ci] announced ${latest.conclusion} for ${repo}`);
    }
  }
}

module.exports = { CIWatch };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { extractAnswer, stripAnsi } = require('../src/answer');

test('extracts the newest completed Claude reply and ignores a tool card', () => {
  const terminal = [
    '● Earlier reply that should not be selected.',
    '✻ Cooked for 2s',
    '● Read(src/sync.js)',
    '  ⎿  Read 100 lines',
    '● Shipped the Discord reply path.',
    '  ',
    '  - Keeps the raw terminal transcript',
    '  - Replies with the final prose only',
    '✻ Cooked for 12s',
    '❯',
    'esc to interrupt · 1.2k tokens',
  ].join('\n');

  assert.deepEqual(extractAnswer(terminal, { agent: 'claude' }), {
    answer: 'Shipped the Discord reply path.\n\n- Keeps the raw terminal transcript\n- Replies with the final prose only',
    confidence: 'high',
    kind: 'prose',
  });
});

test('extracts a completed Codex reply while dropping tool-card output', () => {
  const terminal = [
    '• Ran git status --short',
    '  │ ?? answer.js',
    '  └ completed in 30ms',
    '• Implemented answer extraction.',
    '  ',
    '  The final reply now preserves Markdown.',
    '─ Worked for 5s ─────',
  ].join('\n');

  assert.deepEqual(extractAnswer(terminal, { agent: 'codex' }), {
    answer: 'Implemented answer extraction.\n\nThe final reply now preserves Markdown.',
    confidence: 'high',
    kind: 'prose',
  });
});

test('does not call a live, unfinished terminal frame a final answer', () => {
  const terminal = [
    '● I have identified the failing test and am applying the fix.',
    '❯',
    'esc to interrupt · 1.2k tokens',
  ].join('\n');

  const result = extractAnswer(terminal, { agent: 'claude' });
  assert.equal(result.answer, 'I have identified the failing test and am applying the fix.');
  assert.equal(result.confidence, 'low');
  assert.equal(result.kind, 'prose');
});

test('strips ANSI and invisible terminal characters without damaging text', () => {
  assert.equal(stripAnsi('\u001b[32mDone\u001b[0m\u200b'), 'Done');
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { Queue, MAX_PER_AGENT } = require('../src/queue');

// Stands in for the real store: same two methods, kept in memory.
function fakeStore(initial = {}) {
  const meta = { ...initial };
  return {
    getMeta: (k) => meta[k],
    setMeta: (k, v) => {
      meta[k] = v;
    },
    _meta: meta,
  };
}

test('prompts come back out in the order they were typed', () => {
  const q = new Queue({ store: fakeStore() });
  assert.equal(q.push('w1:p1', { text: 'first' }), 1);
  assert.equal(q.push('w1:p1', { text: 'second' }), 2);
  assert.equal(q.shift('w1:p1').text, 'first');
  assert.equal(q.shift('w1:p1').text, 'second');
  assert.equal(q.shift('w1:p1'), null);
});

test('each agent has its own line', () => {
  const q = new Queue({ store: fakeStore() });
  q.push('w1:p1', { text: 'for one' });
  q.push('w2:p1', { text: 'for two' });
  assert.equal(q.size('w1:p1'), 1);
  assert.equal(q.shift('w2:p1').text, 'for two');
  assert.equal(q.size('w1:p1'), 1);
});

// What you typed before a restart is still what you want said afterwards.
test('a queue survives being reloaded from the store', () => {
  const store = fakeStore();
  const first = new Queue({ store });
  first.push('w1:p1', { text: 'remember me', messageId: '42' });

  const second = new Queue({ store });
  assert.equal(second.size('w1:p1'), 1);
  const back = second.shift('w1:p1');
  assert.equal(back.text, 'remember me');
  assert.equal(back.messageId, '42');
});

test('an emptied queue leaves nothing behind in the store', () => {
  const store = fakeStore();
  const q = new Queue({ store });
  q.push('w1:p1', { text: 'x' });
  q.shift('w1:p1');
  assert.deepEqual(store._meta.promptQueue, {});
});

test('the queue refuses to grow without bound', () => {
  const q = new Queue({ store: fakeStore() });
  for (let i = 0; i < MAX_PER_AGENT; i += 1) q.push('w1:p1', { text: `p${i}` });
  assert.throws(() => q.push('w1:p1', { text: 'one too many' }), /full/);
});

test('a corrupt saved queue is ignored rather than fatal', () => {
  const q = new Queue({ store: fakeStore({ promptQueue: { 'w1:p1': 'not an array' } }) });
  assert.equal(q.size('w1:p1'), 0);
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { observeStart } = require('../src/project');

// Reads the given frames in order, repeating the last one forever.
function frames(list) {
  let i = 0;
  return async () => list[Math.min(i++, list.length - 1)];
}

const FAST = { waitMs: 3000, stepMs: 5 };

test('a dev server that announces its URL counts as serving', async () => {
  const seen = await observeStart(
    frames([
      'ubuntu@nvidia:~/app$ bun run dev',
      ['$ vite', '', '  VITE ready in 300 ms', '  ➜  Local:   http://localhost:3069/'].join('\n'),
    ]),
    FAST,
  );
  assert.equal(seen.state, 'serving');
  assert.equal(seen.port, 3069);
});

// The case that made this necessary: astro refuses to start, and prints the
// URL of the server that is already running. Treating that as success would
// report a dead pane as a live one.
test('a failed launcher is not called serving just because it printed a URL', async () => {
  const dead = [
    'ubuntu@nvidia:~/github/palash.dev$ bun run dev',
    '$ rm -rf node_modules/.vite && astro dev',
    'Another astro dev server is already running.',
    '',
    '  URL:  http://localhost:4321',
    '  PID:  866840',
    '',
    'error: script "dev" exited with code 1',
    'ubuntu@nvidia:~/github/palash.dev$',
  ].join('\n');
  const seen = await observeStart(frames([dead, dead]), FAST);
  assert.equal(seen.state, 'failed');
});

test('a command that simply finishes is reported as exited, not failed', async () => {
  const done = ['ubuntu@nvidia:~/app$ make build', 'built 12 targets', 'ubuntu@nvidia:~/app$'].join(
    '\n',
  );
  const seen = await observeStart(frames([done, done]), FAST);
  assert.equal(seen.state, 'exited');
});

// A shell that has not echoed the command yet looks exactly like one that has
// already finished, so the first read must never decide the outcome.
test('an idle prompt on the first read does not end the watch early', async () => {
  const seen = await observeStart(
    frames([
      'ubuntu@nvidia:~/app$',
      'ubuntu@nvidia:~/app$ bun run dev',
      '  ➜  Local:   http://127.0.0.1:3900/',
    ]),
    FAST,
  );
  assert.equal(seen.state, 'serving');
  assert.equal(seen.port, 3900);
});

test('a server still booting when the watch ends is reported as running', async () => {
  const seen = await observeStart(frames(['compiling…']), { waitMs: 40, stepMs: 5 });
  assert.equal(seen.state, 'running');
});

'use strict';

// narrate() feeds the mid-run commentary in an agent's thread. extractAnswer
// answers "what did it conclude"; this answers "what is it doing right now",
// which is the question you actually have while watching from a phone.

const test = require('node:test');
const assert = require('node:assert/strict');
const { narrate } = require('../src/answer');

const CLAUDE_RUN = [
  '● Let me look at the sync loop first.',
  '● Read(src/sync.js)',
  '  ⎿  Read 100 lines',
  '● Edit(src/sync.js)',
  '  ⎿  Updated 2 additions',
  '● The rename was blocking the tick, so I routed it through renameLater.',
  '✻ Cooked for 12s',
  '❯',
  'esc to interrupt · 1.2k tokens',
].join('\n');

test('reports prose and tool calls in the order they happened', () => {
  const { items } = narrate(CLAUDE_RUN, { agent: 'claude' });
  assert.deepEqual(
    items.map((i) => `${i.kind}:${i.text}`),
    [
      'assistant:Let me look at the sync loop first.',
      'tool:Read(src/sync.js)',
      'tool:Edit(src/sync.js)',
      'assistant:The rename was blocking the tick, so I routed it through renameLater.',
    ],
  );
});

// Only the last item can still be half-written, so it is the only one a live
// caller has to hold back.
test('flags the newest item so a live caller can hold it back', () => {
  const { items } = narrate(CLAUDE_RUN, { agent: 'claude' });
  assert.equal(items.filter((i) => i.last).length, 1);
  assert.equal(items[items.length - 1].last, true);
});

test('a tool card contributes its title, never its output', () => {
  const { items } = narrate(CLAUDE_RUN, { agent: 'claude' });
  const joined = items.map((i) => i.text).join('\n');
  assert.ok(!joined.includes('Read 100 lines'));
  assert.ok(!joined.includes('Updated 2 additions'));
});

test('reads a codex transcript too', () => {
  const terminal = [
    '• Ran git status --short',
    '  │ ?? answer.js',
    '  └ completed in 30ms',
    '• Implemented answer extraction.',
    '─ Worked for 5s ─────',
  ].join('\n');

  const { items, profile } = narrate(terminal, { agent: 'codex' });
  assert.equal(profile, 'codex');
  assert.deepEqual(
    items.map((i) => `${i.kind}:${i.text}`),
    ['tool:Ran git status --short', 'assistant:Implemented answer extraction.'],
  );
});

test('an unreadable capture narrates nothing rather than guessing', () => {
  assert.deepEqual(narrate('', { agent: 'claude' }).items, []);
  assert.deepEqual(narrate('{"error":"pane not found"}', { agent: 'claude' }).items, []);
});

// A long tool title would otherwise push the rolling activity line over
// Discord's message limit on its own.
test('a very long tool title is clamped', () => {
  const terminal = ['● Bash(' + 'x'.repeat(300) + ')', '  ⎿  ok'].join('\n');
  const { items } = narrate(terminal, { agent: 'claude' });
  assert.equal(items.length, 1);
  assert.ok(items[0].text.length <= 90);
  assert.ok(items[0].text.endsWith('…'));
});

// A capture window that starts mid-message has lost the marker that said who
// was speaking. In practice that is usually the tail of the human's own prompt,
// wrapped and indented exactly like a reply — posting it back into the thread
// as if the agent had said it is worse than saying nothing.
test('an unmarked opening fragment is not attributed to the agent', () => {
  const terminal = [
    '  what you are about to do, then write f.txt with a sentence about deserts;',
    '  then read both back and count the words in each.',
    '● First, I am about to create f.txt with a sentence about deserts.',
    '  Read 1 file',
    '✻ Cooked for 3s',
  ].join('\n');

  const { items } = narrate(terminal, { agent: 'claude' });
  assert.deepEqual(
    items.map((i) => `${i.kind}:${i.text}`),
    ['assistant:First, I am about to create f.txt with a sentence about deserts.', 'tool:Read 1 file'],
  );
});

'use strict';

// Pure helpers from the sync loop. These are the parts where a mistake shows up
// as a duplicated or missing message in a thread rather than as an exception.

const test = require('node:test');
const assert = require('node:assert/strict');
const { Sync } = require('../src/sync');

test('an exact repeat of a narration item is not said twice', () => {
  const seen = new Set(['assistant:I will start with the sync loop.']);
  assert.equal(
    Sync.alreadySaid(seen, { kind: 'assistant', text: 'I will start with the sync loop.' }),
    true,
  );
});

// The capture window scrolls, so a long message loses its opening lines and
// comes back as a shorter block. That is the same message, not a new one.
test('the tail of a message already posted is not posted again', () => {
  const full =
    'I will check each file in turn.\n\nFirst, a.txt: counting the words in its sentence about the sea.';
  const seen = new Set([`assistant:${full}`]);
  assert.equal(
    Sync.alreadySaid(seen, {
      kind: 'assistant',
      text: 'First, a.txt: counting the words in its sentence about the sea.',
    }),
    true,
  );
});

test('a genuinely new thought still gets through', () => {
  const seen = new Set(['assistant:I will check each file in turn.']);
  assert.equal(
    Sync.alreadySaid(seen, { kind: 'assistant', text: 'b.txt has 11 words.' }),
    false,
  );
});

// Tool labels are short and repeat verbatim ("Read 1 file"), so containment
// would collapse unrelated ones. They are matched exactly and nothing else.
test('tool labels are matched exactly, never by containment', () => {
  const seen = new Set(['assistant:Read 1 file and then some more of them']);
  assert.equal(Sync.alreadySaid(seen, { kind: 'tool', text: 'Read 1 file' }), false);
  seen.add('tool:Read 1 file');
  assert.equal(Sync.alreadySaid(seen, { kind: 'tool', text: 'Read 1 file' }), true);
});

test('delta emits only what is new in an overlapping window', () => {
  assert.deepEqual(Sync.delta(['a', 'b', 'c'], ['b', 'c', 'd']), ['d']);
  assert.deepEqual(Sync.delta([], ['a']), ['a']);
  // No overlap at all: the agent scrolled further than one window between
  // reads, so everything in the new window is new to us.
  assert.deepEqual(Sync.delta(['a'], ['x', 'y']), ['x', 'y']);
});

// The last item in a capture is either half-written or — when somebody in the
// thread is waiting on an answer — the answer itself, which #postAnswer posts
// as a reply to their message. Narrating it too would say it twice.
test('the newest item is withheld while the agent is still writing', () => {
  const items = [
    { kind: 'assistant', text: 'Starting on the sync loop now.', last: false },
    { kind: 'tool', text: 'Read 1 file', last: false },
    { kind: 'assistant', text: 'Here is what I found in the end.', last: true },
  ];
  const held = Sync.freshNarration(items, new Set(), true);
  assert.deepEqual(
    held.map((i) => i.text),
    ['Starting on the sync loop now.', 'Read 1 file'],
  );

  // Once it is settled and nobody is waiting on a reply, it goes out.
  const all = Sync.freshNarration(items, new Set(), false);
  assert.equal(all.length, 3);
});

test('a withheld item is still available on the next pass', () => {
  const items = [
    { kind: 'assistant', text: 'One.', last: false },
    { kind: 'assistant', text: 'Two, the final word.', last: true },
  ];
  const seen = new Set();
  assert.deepEqual(Sync.freshNarration(items, seen, true).map((i) => i.text), ['One.']);
  assert.deepEqual(
    Sync.freshNarration(items, seen, false).map((i) => i.text),
    ['Two, the final word.'],
  );
});

// The prompt is already in the thread as the message that was typed.
test('the human turn is recorded but never posted back', () => {
  const seen = new Set();
  const fresh = Sync.freshNarration(
    [
      { kind: 'user', text: 'count the words in each file', last: false },
      { kind: 'assistant', text: 'Counting them now.', last: false },
    ],
    seen,
    false,
  );
  assert.deepEqual(fresh.map((i) => i.text), ['Counting them now.']);
  assert.ok(seen.has('user:count the words in each file'));
});

