// queue.js — hold prompts aimed at a busy agent until it is free again.
//
// Typing at an agent that is mid-task used to interleave your text with its
// own work, which at best is ignored and at worst derails it. Queue instead,
// and hand the prompt over the moment the agent settles.
//
// State lives in the store so a restart does not lose what you asked for. Each
// entry keeps the message it came from, so the eventual answer can reply to the
// question rather than arriving as an orphan.

const KEY = 'promptQueue';
const MAX_PER_AGENT = 20;

class Queue {
  constructor({ store, log = console } = {}) {
    this.store = store;
    this.log = log;
    this.map = new Map();
    this.#load();
  }

  #load() {
    try {
      const saved = this.store?.getMeta?.(KEY) || {};
      for (const [paneId, items] of Object.entries(saved)) {
        if (Array.isArray(items) && items.length) this.map.set(paneId, items.slice(0, MAX_PER_AGENT));
      }
    } catch (e) {
      this.log.error?.(`[queue] could not restore: ${e.message}`);
    }
  }

  #persist() {
    if (!this.store?.setMeta) return;
    const out = {};
    for (const [paneId, items] of this.map) if (items.length) out[paneId] = items;
    try {
      this.store.setMeta(KEY, out);
    } catch (e) {
      this.log.error?.(`[queue] could not persist: ${e.message}`);
    }
  }

  // Returns this entry's position in line (1 = next up).
  push(paneId, entry) {
    const items = this.map.get(paneId) || [];
    if (items.length >= MAX_PER_AGENT) {
      throw new Error(`queue for ${paneId} is full (${MAX_PER_AGENT})`);
    }
    items.push({ ...entry, at: Date.now() });
    this.map.set(paneId, items);
    this.#persist();
    return items.length;
  }

  shift(paneId) {
    const items = this.map.get(paneId);
    if (!items?.length) return null;
    const next = items.shift();
    if (items.length) this.map.set(paneId, items);
    else this.map.delete(paneId);
    this.#persist();
    return next;
  }

  list(paneId) {
    return [...(this.map.get(paneId) || [])];
  }

  size(paneId) {
    return this.map.get(paneId)?.length || 0;
  }

  clear(paneId) {
    const n = this.size(paneId);
    this.map.delete(paneId);
    this.#persist();
    return n;
  }

  // Drop everything for an agent that no longer exists.
  forget(paneId) {
    if (this.map.delete(paneId)) this.#persist();
  }
}

module.exports = { Queue, MAX_PER_AGENT };

// project.js — work out how to run and test a project from what's on disk.
//
// Deliberately evidence-based: every command returned is one that actually
// exists in a manifest (a package.json script, a Makefile target, a justfile
// recipe, a Cargo/zig build). Nothing is inferred from convention alone, so we
// never hand Discord a command that fails the moment it runs.

const fs = require('node:fs');
const path = require('node:path');
const { execFile } = require('node:child_process');

function readJson(p) {
  try {
    return JSON.parse(fs.readFileSync(p, 'utf8'));
  } catch {
    return null;
  }
}

function readText(p) {
  try {
    return fs.readFileSync(p, 'utf8');
  } catch {
    return '';
  }
}

// Which JS runner the project actually uses, based on its lockfile / manifest.
function jsRunner(root, pkg) {
  if (pkg?.packageManager?.startsWith('bun')) return 'bun';
  if (fs.existsSync(path.join(root, 'bun.lockb')) || fs.existsSync(path.join(root, 'bun.lock'))) {
    return 'bun';
  }
  if (fs.existsSync(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
  if (fs.existsSync(path.join(root, 'yarn.lock'))) return 'yarn';
  return 'npm';
}

function makeTargets(root) {
  const mk = readText(path.join(root, 'Makefile'));
  if (!mk) return [];
  return [...mk.matchAll(/^([a-zA-Z][\w-]*):(?!=)/gm)].map((m) => m[1]);
}

function justRecipes(root) {
  const j = readText(path.join(root, 'justfile')) || readText(path.join(root, 'Justfile'));
  if (!j) return [];
  return [...j.matchAll(/^([a-zA-Z][\w-]*):/gm)].map((m) => m[1]);
}

// Detect a project's identity and its real run/test commands.
function detect(root) {
  const out = {
    root,
    name: path.basename(root),
    type: 'unknown',
    run: null,
    test: null,
    port: null,
    evidence: [],
  };
  if (!root || !fs.existsSync(root)) return out;

  const pkgPath = path.join(root, 'package.json');
  const pkg = readJson(pkgPath);
  const targets = makeTargets(root);
  const recipes = justRecipes(root);

  // --- JavaScript / TypeScript ---
  if (pkg) {
    out.type = 'node';
    out.evidence.push('package.json');
    const runner = jsRunner(root, pkg);
    const scripts = pkg.scripts || {};
    const runScript = ['dev', 'start', 'serve'].find((s) => scripts[s]);
    const testScript = ['test', 'test:unit', 'test:frontend'].find((s) => scripts[s]);
    if (runScript) out.run = `${runner} run ${runScript}`;
    if (testScript) out.test = `${runner} run ${testScript}`;
    // A port declared in a script or vite config is better than a guess.
    const hay = JSON.stringify(scripts) + readText(path.join(root, 'vite.config.js'));
    const m = hay.match(/(?:PORT|port)\D{0,8}(\d{4,5})/);
    if (m) out.port = Number(m[1]);
  }

  // --- Rust ---
  if (fs.existsSync(path.join(root, 'Cargo.toml'))) {
    out.type = out.type === 'unknown' ? 'rust' : out.type;
    out.evidence.push('Cargo.toml');
    out.run = out.run || 'cargo run';
    out.test = out.test || 'cargo test';
  }

  // --- Zig ---
  if (fs.existsSync(path.join(root, 'build.zig'))) {
    out.type = out.type === 'unknown' ? 'zig' : out.type;
    out.evidence.push('build.zig');
    out.run = out.run || 'zig build run';
    out.test = out.test || 'zig build test';
  }

  // --- Python ---
  if (
    fs.existsSync(path.join(root, 'pyproject.toml')) ||
    fs.existsSync(path.join(root, 'requirements.txt'))
  ) {
    out.type = out.type === 'unknown' ? 'python' : out.type;
    out.evidence.push('pyproject/requirements');
    out.test = out.test || 'pytest';
  }

  // --- Make / just win when present: they encode what the author intended ---
  if (targets.length) {
    out.evidence.push('Makefile');
    if (targets.includes('run')) out.run = 'make run';
    if (targets.includes('dev')) out.run = 'make dev';
    if (targets.includes('test')) out.test = 'make test';
  }
  if (recipes.length) {
    out.evidence.push('justfile');
    if (recipes.includes('run')) out.run = out.run || 'just run';
    if (recipes.includes('test')) out.test = out.test || 'just test';
  }

  return out;
}

// Run a bounded command and capture its result. Used for tests, never for dev
// servers — those belong in a herdr pane where they can live and stream.
function runBounded(cmd, cwd, timeoutMs = 300000) {
  return new Promise((resolve) => {
    const started = Date.now();
    execFile(
      'bash',
      ['-lc', cmd],
      { cwd, timeout: timeoutMs, maxBuffer: 8 * 1024 * 1024, killSignal: 'SIGKILL' },
      (err, stdout, stderr) => {
        resolve({
          cmd,
          cwd,
          ok: !err,
          timedOut: !!err?.killed,
          code: err?.code ?? 0,
          ms: Date.now() - started,
          stdout: stdout || '',
          stderr: stderr || '',
        });
      },
    );
  });
}

// Having launched a command we watch its pane rather than assume it worked. A
// dev server announces a URL; a failure prints an error and hands the shell
// straight back. `read` returns the pane's visible text, and is injected so
// this stays testable without a terminal.
const SERVE_URL = /https?:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0)(?::(\d+))?[^\s`'"]*/i;
const DIED = /(?:exited with code|command not found|No such file or directory|^\s*error[: ])/im;

async function observeStart(read, { waitMs = 9000, stepMs = 900 } = {}) {
  const deadline = Date.now() + waitMs;
  let last = '';
  let polls = 0;
  while (Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, stepMs));
    last = (await read().catch(() => '')) || '';
    polls += 1;

    // Whether the process is still alive decides everything, so test that
    // first: a failing launcher often prints a URL inside its own error
    // message, and reading that as success would be exactly backwards.
    const lines = last.split('\n').filter((l) => l.trim());
    const back = /[$#%]\s*$/.test(lines[lines.length - 1] || '');
    if (back) {
      // The first read can catch the shell before it has even echoed the
      // command, which looks identical to "already finished" — so wait one
      // more round before calling it. Either way, a pane sitting at a prompt
      // has nothing serving, so don't look for a URL in it.
      if (polls > 1) return { state: DIED.test(last) ? 'failed' : 'exited', output: last };
      continue;
    }

    const url = last.match(SERVE_URL);
    if (url) return { state: 'serving', url: url[0], port: url[1] ? Number(url[1]) : null };
  }
  return { state: 'running', output: last };
}

// A repo root often isn't where the app lives — this one keeps its bot in
// herdr-discord-bot/. When the root yields no commands, look one level down and
// adopt the single subdirectory that does. Only unambiguous cases are adopted:
// if two subprojects both qualify, we would be guessing.
function detectDeep(root) {
  const top = detect(root);
  if (top.run || top.test) return top;

  let entries = [];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return top;
  }

  const candidates = [];
  for (const e of entries) {
    if (!e.isDirectory()) continue;
    if (e.name.startsWith('.') || e.name === 'node_modules') continue;
    const sub = detect(path.join(root, e.name));
    if (sub.run || sub.test) candidates.push(sub);
  }

  if (candidates.length === 1) {
    const only = candidates[0];
    only.adoptedFrom = root;
    return only;
  }
  if (candidates.length > 1) {
    top.ambiguous = candidates.map((c) => c.name);
  }
  return top;
}

module.exports = { detect, detectDeep, runBounded, observeStart };

// Thin, safe wrapper around the `herdr` CLI.
// Everything is invoked via execFile with an argv array — no shell string is
// ever constructed from user input, so Discord text cannot inject commands.

const { execFile } = require('node:child_process');

const HERDR_BIN = process.env.HERDR_BIN || 'herdr';
const EXEC_TIMEOUT_MS = Number(process.env.HERDR_TIMEOUT_MS || 15000);

function runHerdr(args) {
  return new Promise((resolve, reject) => {
    execFile(
      HERDR_BIN,
      args,
      { timeout: EXEC_TIMEOUT_MS, maxBuffer: 8 * 1024 * 1024 },
      (err, stdout, stderr) => {
        if (err) {
          const msg = (stderr && stderr.trim()) || err.message;
          reject(new Error(`herdr ${args.join(' ')} failed: ${msg}`));
          return;
        }
        resolve(stdout);
      },
    );
  });
}

async function runHerdrJson(args) {
  const out = await runHerdr(args);
  const trimmed = out.trim();
  if (!trimmed) return {};
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    // Some subcommands print plain text; return it raw for callers that want it.
    return { _raw: out };
  }
}

// ---- High-level operations -------------------------------------------------

async function listAgents() {
  const data = await runHerdrJson(['agent', 'list']);
  const agents = data?.result?.agents || [];
  return agents.map(normalizeAgent);
}

async function getAgent(target) {
  const data = await runHerdrJson(['agent', 'get', target]);
  const a = data?.result?.agent;
  if (!a) throw new Error(`No agent found for target "${target}"`);
  return normalizeAgent(a);
}

async function readAgent(target, lines = 40) {
  const out = await runHerdr([
    'agent',
    'read',
    target,
    '--lines',
    String(lines),
    '--format',
    'text',
  ]);
  return out;
}

// Send raw key presses (e.g. 'esc', 'enter', 'y') to an agent. Used to answer
// approval prompts and to interrupt a running turn.
async function sendKeys(target, keys) {
  const list = Array.isArray(keys) ? keys : [keys];
  await runHerdr(['agent', 'send-keys', target, ...list.map(String)]);
  return true;
}

async function promptAgent(target, text) {
  // No --wait here: keep the Discord interaction fast; caller can poll status.
  await runHerdr(['agent', 'prompt', target, text]);
  return true;
}

function normalizeAgent(a) {
  return {
    paneId: a.pane_id,
    agent: a.agent,
    status: a.agent_status,
    cwd: a.cwd,
    title: a.terminal_title_stripped || a.terminal_title || '',
    focused: !!a.focused,
    workspaceId: a.workspace_id,
    tabId: a.tab_id,
    sessionValue: a.agent_session?.value,
  };
}

// Resolve a user-supplied target to a concrete pane_id.
// Accepts: an exact pane_id (e.g. "wR:p2"), or a case-insensitive substring of
// the agent title or cwd. Throws a helpful error on no/ambiguous match.
async function resolveTarget(input) {
  const agents = await listAgents();
  const q = String(input).trim();

  const exact = agents.find((a) => a.paneId === q);
  if (exact) return exact;

  const lc = q.toLowerCase();
  const matches = agents.filter(
    (a) =>
      a.paneId.toLowerCase() === lc ||
      a.title.toLowerCase().includes(lc) ||
      a.cwd.toLowerCase().includes(lc),
  );

  if (matches.length === 1) return matches[0];
  if (matches.length === 0) {
    throw new Error(
      `No agent matches "${input}". Use \`/agents\` to see valid pane IDs.`,
    );
  }
  const list = matches
    .slice(0, 10)
    .map((a) => `\`${a.paneId}\` — ${a.title || a.cwd}`)
    .join('\n');
  throw new Error(
    `"${input}" is ambiguous (${matches.length} matches):\n${list}\nUse an exact pane ID.`,
  );
}

module.exports = {
  listAgents,
  getAgent,
  readAgent,
  promptAgent,
  sendKeys,
  resolveTarget,
};

// dashboard.js — one message in #agent-control that always shows the whole
// herdr picture. It is edited in place on every change rather than reposted,
// so the channel stays a live panel instead of a scrolling log.

const { EmbedBuilder } = require('discord.js');

const { STATUS_EMOJI } = require('./format');

const RANK = { blocked: 0, working: 1, done: 2, idle: 3, unknown: 4 };

function shorten(s, n) {
  const t = String(s || '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/[⠇⠏⠋⠙⠹⠸⠼⠴⠦⠧◐◑◒◓✳]/g, '')
    .trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
}

function buildEmbed(agents, { threadsByPane = new Map(), stamp, guildId } = {}) {
  const counts = { blocked: 0, working: 0, done: 0, idle: 0, unknown: 0 };
  for (const a of agents) counts[a.status] = (counts[a.status] || 0) + 1;

  // group by workspace, most urgent workspace first
  const byWs = new Map();
  for (const a of agents) {
    if (!byWs.has(a.workspaceId)) byWs.set(a.workspaceId, []);
    byWs.get(a.workspaceId).push(a);
  }

  const wsBlocks = [...byWs.entries()]
    .map(([wsId, list]) => {
      list.sort((x, y) => (RANK[x.status] ?? 9) - (RANK[y.status] ?? 9));
      const urgency = Math.min(...list.map((a) => RANK[a.status] ?? 9));
      const project = shorten(list[0].cwd.split('/').filter(Boolean).pop() || wsId, 24);
      const lines = list.map((a) => {
        const e = STATUS_EMOJI[a.status] || '⚪';
        const tid = threadsByPane.get(a.paneId);
        const label = shorten(a.title || a.cwd.split('/').pop(), 42);
        // A <#id> mention renders as "unknown" for threads the reader hasn't
        // joined, so link by URL instead — always shows the pane id and jumps.
        const link =
          tid && guildId
            ? `[\`${a.paneId}\`](https://discord.com/channels/${guildId}/${tid})`
            : `\`${a.paneId}\``;
        return `${e} ${link} · ${label}`;
      });
      return { urgency, text: `**${project}** \`${wsId}\`\n${lines.join('\n')}` };
    })
    .sort((a, b) => a.urgency - b.urgency)
    .map((b) => b.text);

  let desc = wsBlocks.join('\n\n');
  if (desc.length > 3900) desc = desc.slice(0, 3890) + '\n…';

  const headline =
    `${STATUS_EMOJI.blocked} ${counts.blocked || 0} blocked · ` +
    `${STATUS_EMOJI.working} ${counts.working || 0} working · ` +
    `${STATUS_EMOJI.done} ${counts.done || 0} done · ` +
    `${STATUS_EMOJI.idle} ${counts.idle || 0} idle`;

  const color = counts.blocked ? 0xed4245 : counts.working ? 0xfaa61a : 0x57f287;

  return new EmbedBuilder()
    .setTitle(`herdr — ${agents.length} agents`)
    .setDescription(`${headline}\n\n${desc || '_no agents_'}`)
    .setColor(color)
    .setFooter({ text: `updated ${stamp || new Date().toTimeString().slice(0, 8)}` });
}

class Dashboard {
  constructor({ channel, store, log = console }) {
    this.channel = channel;
    this.store = store;
    this.log = log;
    this.messageId = store?.getMeta?.('dashboardMessageId') || null;
    this.last = '';
  }

  async render(agents, threadsByPane) {
    const embed = buildEmbed(agents, {
      threadsByPane,
      guildId: this.channel?.guildId || this.channel?.guild?.id,
    });
    // Skip the API call when nothing visible changed.
    const sig = JSON.stringify(embed.data.description) + embed.data.title;
    if (sig === this.last && this.messageId) return;
    this.last = sig;

    try {
      if (this.messageId) {
        const msg = await this.channel.messages.fetch(this.messageId).catch(() => null);
        if (msg) {
          await msg.edit({ embeds: [embed] });
          return;
        }
        this.messageId = null; // it was deleted; fall through and repost
      }
      const msg = await this.channel.send({ embeds: [embed] });
      this.messageId = msg.id;
      this.store?.setMeta?.('dashboardMessageId', msg.id);
      await msg.pin().catch(() => {});
    } catch (e) {
      this.log.error('[dashboard] render failed:', e.message);
    }
  }
}

module.exports = { Dashboard, buildEmbed };

// handoff.js — move work from one agent (and provider) to another.
//
// A note on "zero-token" handoff: it isn't achievable. Every provider ingests
// history in its own format, and none of them will accept another's cached
// state, so the receiving agent necessarily re-reads whatever context it is
// given. What IS achievable is making that context small: instead of replaying
// a 50k-token transcript, hand over a structured brief — goal, state, decisions,
// files, next step — which costs one to two thousand tokens and carries the
// facts a fresh agent actually needs.
//
// The lossy part is judgement, not facts: the brief says what was decided, not
// every alternative that was considered and discarded.

const herdr = require('./herdr');
const { extractAnswer } = require('./answer');
const { execFile } = require('node:child_process');

function git(args, cwd) {
  return new Promise((resolve) => {
    execFile('git', args, { cwd, timeout: 8000 }, (err, stdout) =>
      resolve(err ? '' : String(stdout || '').trim()),
    );
  });
}

// Build a provider-neutral brief from what can be observed about an agent:
// its own last message, plus the actual state of its working tree.
async function buildBrief(paneId, { note } = {}) {
  const agent = await herdr.getAgent(paneId);
  const terminal = await herdr.readAgent(paneId, 160).catch(() => '');
  const { answer } = extractAnswer(terminal, { agent: agent.agent });

  const cwd = agent.cwd;
  const [branch, status, recent, diffstat] = await Promise.all([
    git(['rev-parse', '--abbrev-ref', 'HEAD'], cwd),
    git(['status', '--porcelain'], cwd),
    git(['log', '--oneline', '-8'], cwd),
    git(['diff', '--stat', 'HEAD'], cwd),
  ]);

  const changed = status
    .split('\n')
    .filter(Boolean)
    .slice(0, 25)
    .map((l) => `  ${l}`)
    .join('\n');

  const sections = [
    `# Handoff brief`,
    ``,
    `You are taking over work in progress from another agent (${agent.agent}).`,
    `Continue the task; do not restart it.`,
    ``,
    `## Task`,
    agent.title || '(no title recorded)',
    ``,
    `## Working directory`,
    `${cwd}${branch ? ` (branch ${branch})` : ''}`,
  ];

  if (recent) sections.push(``, `## Recent commits`, recent);
  if (changed) sections.push(``, `## Uncommitted changes`, changed);
  else sections.push(``, `## Uncommitted changes`, '  (working tree clean)');
  if (diffstat) sections.push(``, `## Diff against HEAD`, diffstat.split('\n').slice(-12).join('\n'));

  if (answer) {
    sections.push(
      ``,
      `## Where the previous agent left off (its own words)`,
      answer.split('\n').slice(0, 40).join('\n'),
    );
  }
  if (note) sections.push(``, `## Operator note`, note);

  sections.push(
    ``,
    `## What to do`,
    `Re-read the files named above before changing them — the brief is a summary,`,
    `not a substitute for the code. Then continue the task.`,
  );

  const text = sections.join('\n');
  return {
    text,
    agent,
    // Rough token estimate so the cost of the handoff is visible, not implied.
    approxTokens: Math.ceil(text.length / 4),
  };
}

module.exports = { buildBrief };

// format.js — presentation helpers: herdr agent state -> Discord surfaces.
//
// Everything here is a pure function. No I/O, no state, no side effects, so it
// can be unit-tested without a Discord client or a running herdr.
//
// Agent object shape (see herdr.js normalizeAgent):
//   { paneId, agent, status, cwd, title, focused, workspaceId, tabId, sessionValue }

const { EmbedBuilder } = require('discord.js');

// ---- Discord hard limits ---------------------------------------------------
const MAX_MESSAGE = 2000; // message content
const MAX_EMBED_DESC = 4000; // embed description (4096 real; 4000 per spec)
const MAX_EMBED_TITLE = 256;
const MAX_FIELD_VALUE = 1024;
const MAX_THREAD_NAME = 100;

const STATUS_EMOJI = {
  idle: '🟢',
  working: '🟡',
  blocked: '🔴',
  done: '✅',
  unknown: '⚪',
};

// Discord embed colors as ints.
const STATUS_COLOR = {
  idle: 0x5865f2, // blurple
  working: 0xfaa61a, // amber
  blocked: 0xed4245, // red
  done: 0x57f287, // green
  unknown: 0x99aab5, // grey
};

// Sort order for lists: the things that might need a human come first.
const STATUS_RANK = {
  blocked: 0,
  working: 1,
  done: 2,
  idle: 3,
  unknown: 4,
};

const UNKNOWN = 'unknown';

function normStatus(status) {
  const s = String(status || '').trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(STATUS_EMOJI, s) ? s : UNKNOWN;
}

function statusEmoji(status) {
  return STATUS_EMOJI[normStatus(status)];
}

function statusColor(status) {
  return STATUS_COLOR[normStatus(status)];
}

function statusRank(status) {
  return STATUS_RANK[normStatus(status)];
}

// Strip newlines, tabs and other control characters; collapse runs of spaces.
function sanitize(text) {
  return String(text == null ? '' : text)
    // eslint-disable-next-line no-control-regex
    .replace(/[\x00-\x1f\x7f-\x9f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function basename(p) {
  const clean = String(p || '').replace(/[/\\]+$/, '');
  if (!clean) return '';
  const parts = clean.split(/[/\\]/);
  return parts[parts.length - 1] || clean;
}

// Truncate to `max` graceful-ly, appending an ellipsis when we cut.
function clamp(text, max, ellipsis = '…') {
  const s = String(text == null ? '' : text);
  if (max <= 0) return '';
  if (s.length <= max) return s;
  if (max <= ellipsis.length) return s.slice(0, max);
  return s.slice(0, max - ellipsis.length).trimEnd() + ellipsis;
}

// Human-friendly name for an agent: its terminal title, else the cwd basename,
// else the pane id.
function agentLabel(agent) {
  const a = agent || {};
  const title = sanitize(a.title);
  if (title) return title;
  const base = sanitize(basename(a.cwd));
  if (base) return base;
  return sanitize(a.paneId) || 'agent';
}

// Neutralize ``` so untrusted terminal output can't escape a code fence.
// A zero-width space between the backticks keeps the text visually identical.
function defuseFences(text) {
  return String(text == null ? '' : text).replace(/`{3,}/g, (run) =>
    '`​'.repeat(run.length - 1) + '`',
  );
}

/**
 * Wrap text in a fenced code block that always fits in one Discord message.
 * Keeps the TAIL of long output — for terminal dumps the end is what matters.
 * @param {string} text
 * @param {string} [lang] syntax highlight hint (sanitized)
 * @returns {string} at most MAX_MESSAGE characters
 */
function codeBlock(text, lang = '') {
  const language = String(lang || '')
    .replace(/[^a-zA-Z0-9+#._-]/g, '')
    .slice(0, 20);
  const open = '```' + language + '\n';
  const close = '\n```';
  const budget = MAX_MESSAGE - open.length - close.length;

  // Defuse BEFORE clamping: defusing grows the string, so clamping afterwards
  // is what actually guarantees the length limit.
  let body = defuseFences(text);

  if (body.length > budget) {
    const marker = '…';
    body = body.slice(-(budget - marker.length));
    // A tail cut can land inside a defused run; drop leading backticks so the
    // truncated head can never read as fence syntax.
    body = marker + body.replace(/^`+/, '');
  }
  return open + body + close;
}

/**
 * Rich embed for a single agent.
 * @param {object} agent
 * @returns {import('discord.js').EmbedBuilder}
 */
function agentEmbed(agent) {
  const a = agent || {};
  const status = normStatus(a.status);
  const title = sanitize(a.title) || sanitize(a.paneId) || 'agent';

  const embed = new EmbedBuilder()
    .setTitle(clamp(`${STATUS_EMOJI[status]} ${title}`, MAX_EMBED_TITLE))
    .setColor(STATUS_COLOR[status])
    .addFields(
      {
        name: 'Pane',
        value: clamp('`' + (sanitize(a.paneId) || '—') + '`', MAX_FIELD_VALUE),
        inline: true,
      },
      { name: 'Agent', value: clamp(sanitize(a.agent) || '—', MAX_FIELD_VALUE), inline: true },
      { name: 'Status', value: `${STATUS_EMOJI[status]} ${status}`, inline: true },
      { name: 'CWD', value: clamp(sanitize(a.cwd) || '—', MAX_FIELD_VALUE) },
    );

  const footer = [];
  if (a.workspaceId) footer.push(`ws ${sanitize(a.workspaceId)}`);
  if (a.tabId) footer.push(`tab ${sanitize(a.tabId)}`);
  if (a.focused) footer.push('focused');
  if (footer.length) embed.setFooter({ text: clamp(footer.join(' · '), 2048) });

  return embed;
}

/** blocked -> working -> done -> idle -> unknown, then by pane id. */
function sortAgents(agents) {
  return (Array.isArray(agents) ? agents.slice() : []).sort((a, b) => {
    const d = statusRank(a && a.status) - statusRank(b && b.status);
    if (d !== 0) return d;
    return String((a && a.paneId) || '').localeCompare(String((b && b.paneId) || ''));
  });
}

/** One description line: `🟡 \`wR:p2\` **claude** · working · Fix dictation` */
function agentLine(agent) {
  const a = agent || {};
  const status = normStatus(a.status);
  const pane = sanitize(a.paneId) || '?';
  const name = sanitize(a.agent) || 'agent';
  return `${STATUS_EMOJI[status]} \`${pane}\` **${name}** · ${status} · ${agentLabel(a)}`;
}

/**
 * One embed summarizing many agents.
 * @param {object[]} agents
 * @returns {import('discord.js').EmbedBuilder}
 */
function agentListEmbed(agents) {
  const list = sortAgents(agents);

  // Build up to the description cap without cutting a line in half.
  const lines = [];
  let used = 0;
  let dropped = 0;
  for (const a of list) {
    const line = clamp(agentLine(a), 300);
    const cost = line.length + (lines.length ? 1 : 0);
    if (used + cost > MAX_EMBED_DESC - 24) {
      dropped = list.length - lines.length;
      break;
    }
    lines.push(line);
    used += cost;
  }
  if (dropped > 0) lines.push(`…and ${dropped} more`);

  const description = lines.length ? lines.join('\n') : '_No agents are running._';
  // Color the summary by the most urgent status present.
  const top = list.length ? normStatus(list[0].status) : UNKNOWN;

  return new EmbedBuilder()
    .setTitle(`herdr agents (${list.length})`)
    .setDescription(clamp(description, MAX_EMBED_DESC))
    .setColor(list.length ? STATUS_COLOR[top] : STATUS_COLOR.unknown)
    .setFooter({ text: 'Target commands by pane ID, e.g. /read wR:p2' });
}

/**
 * Stable, Discord-safe thread name for an agent, e.g. `🟡 wR:p2 · Fix dictation`.
 * @param {object} agent
 * @returns {string} 1..100 chars, no newlines or control characters
 */
function threadName(agent) {
  const a = agent || {};
  const emoji = STATUS_EMOJI[normStatus(a.status)];
  const pane = sanitize(a.paneId);
  const label = agentLabel(a);

  const head = pane ? `${emoji} ${pane}` : emoji;
  if (!label || label === pane) return clamp(head, MAX_THREAD_NAME) || 'agent';

  const room = MAX_THREAD_NAME - head.length - 3; // " · "
  if (room < 4) return clamp(head, MAX_THREAD_NAME);
  return `${head} · ${clamp(label, room)}`;
}

/**
 * One-line sentence describing a status transition.
 * e.g. `🟡 → ✅ **done** (was working)`; without a prev status, `✅ **done**`.
 * @param {object} agent
 * @param {string} [prevStatus]
 * @returns {string}
 */
function statusLine(agent, prevStatus) {
  const a = agent || {};
  const now = normStatus(a.status);
  const nowEmoji = STATUS_EMOJI[now];

  if (prevStatus === undefined || prevStatus === null || prevStatus === '') {
    return `${nowEmoji} **${now}**`;
  }
  const prev = normStatus(prevStatus);
  if (prev === now) return `${nowEmoji} **${now}** (unchanged)`;
  return `${STATUS_EMOJI[prev]} → ${nowEmoji} **${now}** (was ${prev})`;
}

module.exports = {
  // constants
  STATUS_EMOJI,
  STATUS_COLOR,
  STATUS_RANK,
  MAX_MESSAGE,
  MAX_EMBED_DESC,
  MAX_THREAD_NAME,
  // helpers
  statusEmoji,
  statusColor,
  statusRank,
  sortAgents,
  agentLabel,
  agentLine,
  defuseFences,
  clamp,
  // renderers
  codeBlock,
  agentEmbed,
  agentListEmbed,
  threadName,
  statusLine,
};

// github.js — read-only GitHub surface via the `gh` CLI.
//
// gh is already installed and authenticated on this machine (account debpalash,
// scopes: repo, read:org, gist), so the bot shells out to it rather than
// managing its own token. As everywhere else, commands are invoked with an argv
// array — no shell string is ever built from user input.
//
// Note: the token has no `workflow` scope, so runs can be read but not
// dispatched or re-run.

const { execFile } = require('node:child_process');
const path = require('node:path');
const fs = require('node:fs');

const GH_BIN = process.env.GH_BIN || 'gh';
const TIMEOUT_MS = Number(process.env.GH_TIMEOUT_MS || 20000);

function gh(args, cwd) {
  return new Promise((resolve, reject) => {
    execFile(
      GH_BIN,
      args,
      { timeout: TIMEOUT_MS, maxBuffer: 8 * 1024 * 1024, cwd: cwd || undefined },
      (err, stdout, stderr) => {
        if (err) {
          const msg = (stderr && stderr.trim()) || err.message;
          reject(new Error(msg.split('\n')[0]));
          return;
        }
        resolve(stdout);
      },
    );
  });
}

async function ghJson(args, cwd) {
  const out = await gh(args, cwd);
  const t = out.trim();
  if (!t) return [];
  try {
    return JSON.parse(t);
  } catch {
    return [];
  }
}

// ---- repo resolution -------------------------------------------------------

// Map a working directory to its "owner/name" slug. Agents carry a cwd, so a
// workspace channel can be tied to whatever repo its agents are working in.
const repoCache = new Map();

async function repoForDir(dir) {
  if (!dir) return null;
  if (repoCache.has(dir)) return repoCache.get(dir);

  // Walk up to the git root so a subdirectory still resolves.
  let d = dir;
  for (let i = 0; i < 6; i++) {
    if (fs.existsSync(path.join(d, '.git'))) break;
    const up = path.dirname(d);
    if (up === d) break;
    d = up;
  }

  let slug = null;
  try {
    const info = await ghJson(['repo', 'view', '--json', 'nameWithOwner'], d);
    slug = info?.nameWithOwner || null;
  } catch {
    slug = null; // not a GitHub repo, or no remote
  }
  repoCache.set(dir, slug);
  return slug;
}

// ---- queries ---------------------------------------------------------------

async function listPRs(repo, { state = 'open', limit = 10 } = {}) {
  const rows = await ghJson([
    'pr', 'list', '-R', repo, '--state', state, '--limit', String(limit),
    '--json', 'number,title,state,author,isDraft,url,headRefName,reviewDecision,updatedAt,additions,deletions',
  ]);
  return (rows || []).map((p) => ({
    number: p.number,
    title: p.title,
    state: p.state,
    draft: !!p.isDraft,
    author: p.author?.login || '?',
    url: p.url,
    branch: p.headRefName,
    review: p.reviewDecision || null,
    updatedAt: p.updatedAt,
    additions: p.additions,
    deletions: p.deletions,
  }));
}

async function listIssues(repo, { state = 'open', limit = 10 } = {}) {
  const rows = await ghJson([
    'issue', 'list', '-R', repo, '--state', state, '--limit', String(limit),
    '--json', 'number,title,state,author,url,labels,updatedAt',
  ]);
  return (rows || []).map((i) => ({
    number: i.number,
    title: i.title,
    state: i.state,
    author: i.author?.login || '?',
    url: i.url,
    labels: (i.labels || []).map((l) => l.name),
    updatedAt: i.updatedAt,
  }));
}

async function listRuns(repo, { limit = 10, branch } = {}) {
  const args = [
    'run', 'list', '-R', repo, '--limit', String(limit),
    '--json', 'databaseId,displayTitle,status,conclusion,workflowName,headBranch,event,createdAt,url',
  ];
  if (branch) args.push('--branch', branch);
  const rows = await ghJson(args);
  return (rows || []).map((r) => ({
    id: r.databaseId,
    title: r.displayTitle,
    status: r.status, // queued | in_progress | completed
    conclusion: r.conclusion, // success | failure | cancelled | null
    workflow: r.workflowName,
    branch: r.headBranch,
    event: r.event,
    createdAt: r.createdAt,
    url: r.url,
  }));
}

// A compact health summary for one repo — what a channel header should show.
async function repoSummary(repo) {
  const [prs, runs] = await Promise.all([
    listPRs(repo, { state: 'open', limit: 30 }).catch(() => []),
    listRuns(repo, { limit: 10 }).catch(() => []),
  ]);
  const latest = runs[0] || null;
  const failing = runs.filter((r) => r.conclusion === 'failure').length;
  return {
    repo,
    openPRs: prs.length,
    drafts: prs.filter((p) => p.draft).length,
    latestRun: latest,
    recentFailures: failing,
  };
}

// ---- presentation ----------------------------------------------------------

const RUN_EMOJI = {
  success: '✅',
  failure: '❌',
  cancelled: '⚪',
  skipped: '⚪',
  timed_out: '⌛',
  in_progress: '🟡',
  queued: '⏳',
};

function runEmoji(run) {
  if (!run) return '⚪';
  if (run.status !== 'completed') return RUN_EMOJI[run.status] || '🟡';
  return RUN_EMOJI[run.conclusion] || '⚪';
}

// Bug reports quote URLs, and truncating one mid-string leaves Discord
// auto-linking a fragment that goes nowhere. Reduce any URL in a title to its
// host so the line stays readable and every link on screen is real.
function titleLine(title, max = 70) {
  const flat = String(title || '').replace(/https?:\/\/([^\s/]+)\S*/g, (_, host) => `\`${host}\``);
  if (flat.length <= max) return flat;
  let cut = flat.slice(0, max).trimEnd();
  // Don't leave a code span hanging open — Discord would swallow the rest.
  if ((cut.match(/`/g) || []).length % 2) cut += '`';
  return cut + '…';
}

function prLine(p) {
  const mark = p.draft ? '📝' : p.review === 'APPROVED' ? '✅' : '🔵';
  return `${mark} [#${p.number}](${p.url}) ${titleLine(p.title)} · _${p.author}_`;
}

function runLine(r) {
  return `${runEmoji(r)} [${r.workflow}](${r.url}) · \`${r.branch}\` · ${
    r.conclusion || r.status
  }`;
}

async function isAvailable() {
  try {
    await gh(['auth', 'status']);
    return true;
  } catch {
    return false;
  }
}

module.exports = {
  gh,
  ghJson,
  repoForDir,
  listPRs,
  listIssues,
  listRuns,
  repoSummary,
  prLine,
  titleLine,
  runLine,
  runEmoji,
  isAvailable,
};

// store.js — tiny JSON-file-backed persistent key/value store.
//
// Purpose: remember how herdr entities map onto Discord entities across bot
// restarts (workspace -> channel, agent pane -> thread), plus a small bag of
// misc state (e.g. the last status we announced for a pane).
//
// Design notes:
//   * Writes are ATOMIC: we write a temp file in the same directory and then
//     rename() over the target, so a crash mid-write can never leave a
//     half-written mapping.json behind.
//   * Writes are DEBOUNCED (default 500ms): status polling can touch the store
//     many times a second; we coalesce that into at most one disk write per
//     window. close() always flushes anything still pending.
//   * A missing or corrupt file is never fatal — we start fresh (and move the
//     corrupt file aside once, so it can be inspected instead of silently lost).
//   * No npm dependencies; node builtins only.

const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');

const DEFAULT_FILE = path.join(__dirname, '..', 'data', 'mapping.json');
const DEFAULT_DEBOUNCE_MS = 500;
const SCHEMA_VERSION = 1;

function emptyData() {
  return {
    version: SCHEMA_VERSION,
    // herdr workspace_id -> Discord channel id
    workspaceChannels: Object.create(null),
    // herdr pane_id -> Discord thread id
    agentThreads: Object.create(null),
    // free-form small state (last-seen status per pane, etc.)
    meta: Object.create(null),
  };
}

// Accept whatever is on disk but guarantee the shape callers rely on.
function normalizeData(raw) {
  const data = emptyData();
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return data;

  const copyStrings = (src, dest) => {
    if (!src || typeof src !== 'object' || Array.isArray(src)) return;
    for (const [k, v] of Object.entries(src)) {
      if (typeof v === 'string' && v) dest[k] = v;
    }
  };

  copyStrings(raw.workspaceChannels, data.workspaceChannels);
  copyStrings(raw.agentThreads, data.agentThreads);

  if (raw.meta && typeof raw.meta === 'object' && !Array.isArray(raw.meta)) {
    for (const [k, v] of Object.entries(raw.meta)) {
      if (v !== undefined) data.meta[k] = v;
    }
  }
  return data;
}

function isString(v) {
  return typeof v === 'string' && v.length > 0;
}

class Store {
  /**
   * @param {object} [opts]
   * @param {string} [opts.file]        path to the JSON file
   * @param {number} [opts.debounceMs]  coalescing window for writes
   */
  constructor(opts = {}) {
    this.file = opts.file || process.env.HERDR_BOT_STORE || DEFAULT_FILE;
    this.debounceMs = Number.isFinite(opts.debounceMs)
      ? Math.max(0, opts.debounceMs)
      : DEFAULT_DEBOUNCE_MS;

    this.data = emptyData();
    this.loaded = false;

    this._timer = null;
    this._dirty = false;
    // Serializes overlapping save() calls so two writers can't interleave.
    this._chain = Promise.resolve();
  }

  // ---- persistence --------------------------------------------------------

  /**
   * Read the file into memory. Safe to call more than once. Never throws for
   * "file missing" or "file is garbage" — those just yield an empty store.
   * @returns {Promise<object>} the in-memory data
   */
  async load() {
    let text;
    try {
      text = await fsp.readFile(this.file, 'utf8');
    } catch (err) {
      if (err.code !== 'ENOENT') {
        console.warn(`[store] could not read ${this.file}: ${err.message} — starting fresh`);
      }
      this.data = emptyData();
      this.loaded = true;
      return this.data;
    }

    if (!text.trim()) {
      // Zero-length file: an interrupted write, not corruption worth keeping.
      this.data = emptyData();
      this.loaded = true;
      return this.data;
    }

    try {
      this.data = normalizeData(JSON.parse(text));
    } catch (err) {
      console.warn(`[store] ${this.file} is corrupt (${err.message}) — starting fresh`);
      await this._quarantine(text);
      this.data = emptyData();
    }
    this.loaded = true;
    return this.data;
  }

  /** Synchronous sibling of load(), for use before the event loop is running. */
  loadSync() {
    let text;
    try {
      text = fs.readFileSync(this.file, 'utf8');
    } catch (err) {
      if (err.code !== 'ENOENT') {
        console.warn(`[store] could not read ${this.file}: ${err.message} — starting fresh`);
      }
      this.data = emptyData();
      this.loaded = true;
      return this.data;
    }
    try {
      this.data = text.trim() ? normalizeData(JSON.parse(text)) : emptyData();
    } catch (err) {
      console.warn(`[store] ${this.file} is corrupt (${err.message}) — starting fresh`);
      this.data = emptyData();
    }
    this.loaded = true;
    return this.data;
  }

  /** Write immediately and atomically, cancelling any pending debounced save. */
  save() {
    this._clearTimer();
    this._dirty = false;
    const payload = JSON.stringify(this.data, null, 2) + '\n';
    this._chain = this._chain
      .then(() => this._atomicWrite(payload))
      .catch((err) => {
        console.error(`[store] save failed: ${err.message}`);
      });
    return this._chain;
  }

  /** Blocking atomic write — for process-exit handlers where async is useless. */
  saveSync() {
    this._clearTimer();
    this._dirty = false;
    const payload = JSON.stringify(this.data, null, 2) + '\n';
    const dir = path.dirname(this.file);
    const tmp = this._tmpPath();
    try {
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(tmp, payload, 'utf8');
      fs.renameSync(tmp, this.file);
    } catch (err) {
      try {
        fs.unlinkSync(tmp);
      } catch {
        /* nothing to clean up */
      }
      console.error(`[store] saveSync failed: ${err.message}`);
    }
  }

  /** Flush any pending debounced write. Resolves once the disk is up to date. */
  async flush() {
    if (this._dirty || this._timer) return this.save();
    return this._chain;
  }

  /** Stop the debounce timer and flush. Call this on shutdown. */
  async close() {
    const pending = this._dirty || this._timer !== null;
    this._clearTimer();
    if (pending) await this.save();
    else await this._chain;
    return true;
  }

  // ---- workspace -> channel ----------------------------------------------

  /** @returns {string|null} Discord channel id for a herdr workspace */
  getChannelForWorkspace(workspaceId) {
    if (!isString(workspaceId)) return null;
    return this.data.workspaceChannels[workspaceId] || null;
  }

  setChannelForWorkspace(workspaceId, channelId) {
    if (!isString(workspaceId)) return false;
    if (!isString(channelId)) {
      if (this.data.workspaceChannels[workspaceId] === undefined) return false;
      delete this.data.workspaceChannels[workspaceId];
      this._touch();
      return true;
    }
    if (this.data.workspaceChannels[workspaceId] === channelId) return false;
    this.data.workspaceChannels[workspaceId] = channelId;
    this._touch();
    return true;
  }

  // ---- agent pane -> thread ----------------------------------------------

  /** @returns {string|null} Discord thread id for a herdr pane id */
  getThreadForAgent(paneId) {
    if (!isString(paneId)) return null;
    return this.data.agentThreads[paneId] || null;
  }

  setThreadForAgent(paneId, threadId) {
    if (!isString(paneId)) return false;
    if (!isString(threadId)) return this.deleteThreadForAgent(paneId);
    if (this.data.agentThreads[paneId] === threadId) return false;
    this.data.agentThreads[paneId] = threadId;
    this._touch();
    return true;
  }

  deleteThreadForAgent(paneId) {
    if (!isString(paneId)) return false;
    if (this.data.agentThreads[paneId] === undefined) return false;
    delete this.data.agentThreads[paneId];
    this._touch();
    return true;
  }

  /** @returns {Array<{paneId: string, threadId: string}>} */
  allAgentThreads() {
    return Object.entries(this.data.agentThreads).map(([paneId, threadId]) => ({
      paneId,
      threadId,
    }));
  }

  /** @returns {Array<{workspaceId: string, channelId: string}>} */
  allWorkspaceChannels() {
    return Object.entries(this.data.workspaceChannels).map(([workspaceId, channelId]) => ({
      workspaceId,
      channelId,
    }));
  }

  // ---- misc state ---------------------------------------------------------

  getMeta(key, fallback = undefined) {
    if (!isString(key)) return fallback;
    const v = this.data.meta[key];
    return v === undefined ? fallback : v;
  }

  setMeta(key, value) {
    if (!isString(key)) return false;
    if (value === undefined) {
      if (this.data.meta[key] === undefined) return false;
      delete this.data.meta[key];
      this._touch();
      return true;
    }
    if (this.data.meta[key] === value) return false;
    this.data.meta[key] = value;
    this._touch();
    return true;
  }

  deleteMeta(key) {
    return this.setMeta(key, undefined);
  }

  /** Wipe everything (useful for tests / `/reset`). */
  clear() {
    this.data = emptyData();
    this._touch();
  }

  // ---- internals ----------------------------------------------------------

  _touch() {
    this._dirty = true;
    if (this.debounceMs === 0) {
      this.save();
      return;
    }
    if (this._timer) return; // already coalescing into the pending write
    this._timer = setTimeout(() => {
      this._timer = null;
      if (this._dirty) this.save();
    }, this.debounceMs);
    // Never keep the process alive just for a pending save.
    if (typeof this._timer.unref === 'function') this._timer.unref();
  }

  _clearTimer() {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
  }

  _tmpPath() {
    const rand = Math.random().toString(36).slice(2, 8);
    return path.join(
      path.dirname(this.file),
      `.${path.basename(this.file)}.${process.pid}.${rand}.tmp`,
    );
  }

  async _atomicWrite(payload) {
    await fsp.mkdir(path.dirname(this.file), { recursive: true });
    const tmp = this._tmpPath();
    try {
      const fh = await fsp.open(tmp, 'w');
      try {
        await fh.writeFile(payload, 'utf8');
        // Best-effort durability; not supported everywhere, never fatal.
        await fh.sync().catch(() => {});
      } finally {
        await fh.close();
      }
      await fsp.rename(tmp, this.file);
    } catch (err) {
      await fsp.unlink(tmp).catch(() => {});
      throw err;
    }
  }

  // Keep a copy of an unparseable file so the data isn't silently destroyed.
  async _quarantine(text) {
    try {
      await fsp.writeFile(`${this.file}.corrupt`, text, 'utf8');
    } catch {
      /* best effort only */
    }
  }
}

// Shared instance for the bot process. Callers still have to await load().
const store = new Store();

module.exports = { Store, store, DEFAULT_FILE, SCHEMA_VERSION };

'use strict';

// answer.js — pull the human-facing prose reply out of a coding agent's terminal.
//
// A herdr pane holds a full-screen TUI, not a log: every frame repaints a
// spinner, a token counter, an input box and a status bar, and the model's
// actual sentences are buried between tool invocations, unified diffs and
// shell output. Posting that raw into Discord is unreadable. This module finds
// the most recent assistant *message* and returns it as markdown-ready prose.
//
// The approach is three passes:
//   1. normalise   — ANSI/control stripping, tab expansion, CRLF, footer trim
//   2. segment     — split the transcript into blocks (assistant / tool / user
//                    / chrome) using the marker glyph each agent prints in the
//                    left gutter, then classify each block
//   3. render      — un-wrap the terminal's hard wrapping and drop in-block
//                    noise, yielding markdown
//
// Per-agent differences live in the PROFILES table below; unknown agents get a
// generic profile that tries every known layout and keeps whichever segments
// best, falling back to a purely heuristic sweep.
//
// Nothing here throws: every exported function is wrapped and degrades to an
// empty result on garbage input.

// ---------------------------------------------------------------------------
// low-level text hygiene
// ---------------------------------------------------------------------------

// CSI/SGR and friends. Kept deliberately broad — terminal captures occasionally
// carry partial sequences.
const ANSI_CSI =
  /[\u001b\u009b][[\]()#;?]*(?:(?:[a-zA-Z\d]*(?:;[-a-zA-Z\d/#&.:=?%@~_]*)*)?\u0007|(?:\d{1,4}(?:;\d{0,4})*)?[\dA-PR-TZcf-nq-uy=><~])/g;
// OSC ... BEL|ST (window titles, hyperlinks).
const ANSI_OSC = /\u001b\][\s\S]*?(?:\u0007|\u001b\\)/g;
// Leftover control bytes, minus \t \n \r which are handled structurally.
const CTRL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;
// Zero-width / bidi junk some TUIs emit around glyphs.
const INVISIBLE = /[\u200b-\u200f\u2028\u2029\ufeff]/g;

function stripAnsi(s) {
  if (typeof s !== 'string' || !s) return '';
  return s.replace(ANSI_OSC, '').replace(ANSI_CSI, '').replace(CTRL, '').replace(INVISIBLE, '');
}

// Terminal cells are one column wide for our purposes; the only thing that
// really matters is that tabs don't skew indent detection.
function expandTabs(s) {
  return s.replace(/\t/g, '    ');
}

function toLines(text) {
  if (typeof text !== 'string' || !text) return [];
  return stripAnsi(text)
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((l) => expandTabs(l).replace(/[  ]+$/, ''));
}

function indentOf(line) {
  const m = /^[  ]*/.exec(line);
  return m ? m[0].length : 0;
}

// ---------------------------------------------------------------------------
// chrome — the furniture every frame repaints
// ---------------------------------------------------------------------------

// Box drawing (U+2500–U+257F), block elements (U+2580–U+259F) and ASCII rules.
const RULE_ONLY = /^[\s─-╿▀-▟_=~—–-]+$/;
// An input box whose prompt glyph stands alone.
const EMPTY_PROMPT = /^[❯>»›◇▸]\s*$/;
// Spinner / "Worked for" / thinking-verb lines. These glyphs are never used as
// a content bullet by any of the agents we support.
const STATUS_GLYPH =
  /^[✻✳✽✢✶✷✸✹✺◐◑◒◓◔◕⠇⠏⠋⠙⠹⠸⠼⠴⠦⠧⣾⣽⣻⢿⡿⣟⣯⣷]\s/;
// The recap widget claude rotates under a finished turn.
const RECAP = /^※\s|\(disable recaps in \/config\)/;
// Status bars / hint bars, both agents.
const STATUS_BAR =
  /(esc to interrupt|shift\+tab to cycle|bypass permissions on|auto mode on|accept edits on|plan mode on|← for agents|ctrl\+t to (?:hide|view)|ctrl\+p commands|ctrl\+o to (?:expand|see)|to view transcript|\/ps to view|\/stop to close|↓ to manage|↓ to expand|newline$)/i;
// "(1m 50s · ↓ 6.0k tokens)" style counters wherever they appear.
const TOKEN_COUNTER = /\(\s*\d+(?:\.\d+)?\s*[hms].*?(?:tokens?|esc)\b/i;
// codex's own footer + exec bookkeeping.
const CODEX_EXEC_STATUS = /^(?:status|file changes|token usage|context left):\s/i;
const CODEX_APPROVAL = /^✔\s+You approved\b/;
const CODEX_WORKED = /^─\s+Worked for\b/;
const CODEX_MODEL_BAR = /^[\w.\-]+\s.*·\s*~?\/[^\s]*/;
// "… +52 lines (ctrl + t to view transcript)"
const TRUNCATION = /^…\s*\+\d+\s+lines?\b/;
// Welcome / login boxes.
const BOX_EDGE = /^[╭╰╮╯┌└┐┘]/;
const BOX_ROW = /^│.*[│╮╯]\s*$/;
// Rotating tips, claude.
const TIP = /^(?:⎿\s+)?Tip:\s/i;

/**
 * True when a line is pure TUI furniture — something that repaints every frame
 * and carries no transcript content. Superset of the original Sync.isChrome.
 *
 * @param {string} line
 * @returns {boolean}
 */
function isChrome(line) {
  if (typeof line !== 'string') return true;
  const s = line.trim();
  if (!s) return true;
  if (RULE_ONLY.test(s)) return true; // rules / box drawing / block glyphs
  if (EMPTY_PROMPT.test(s)) return true; // bare input prompt
  if (BOX_EDGE.test(s) || BOX_ROW.test(s)) return true; // welcome box
  if (STATUS_BAR.test(s)) return true; // status / hint bar
  if (STATUS_GLYPH.test(s)) return true; // spinner, "Worked for 9m 54s"
  if (RECAP.test(s)) return true; // recap widget
  if (TOKEN_COUNTER.test(s)) return true; // token/elapsed counter
  if (TIP.test(s)) return true; // rotating tips
  if (TRUNCATION.test(s)) return true; // "… +52 lines"
  if (CODEX_EXEC_STATUS.test(s)) return true; // "status: Completed · exit 0"
  if (CODEX_APPROVAL.test(s)) return true; // "✔ You approved codex to run …"
  if (CODEX_WORKED.test(s)) return true; // "─ Worked for 11m 11s ─────"
  if (/^■\s+Conversation interrupted/.test(s)) return true;
  if (/^to report the issue\.$/.test(s)) return true; // wrapped tail of the above
  if (/^↳\s/.test(s)) return true; // "↳ Interacted with background terminal"
  if (/^\+\s*Thought:\s/.test(s)) return true; // opencode thinking timer
  if (/^▣\s/.test(s)) return true; // opencode turn footer "▣ Build · model · 12.7s"
  return false;
}

/**
 * Drop every chrome line. Order-preserving, allocation-light, never throws.
 *
 * @param {string[]|string} lines
 * @returns {string[]}
 */
function stripChrome(lines) {
  try {
    const arr = Array.isArray(lines) ? lines : toLines(lines);
    const out = [];
    for (let i = 0; i < arr.length; i++) {
      const l = arr[i];
      if (typeof l !== 'string') continue;
      if (!isChrome(l)) out.push(l);
    }
    return out;
  } catch {
    return [];
  }
}

// The status bar is the last line of the live frame; anything at or after it
// (background-task panel, model picker hints) is furniture. Trim it so those
// rows can never be mistaken for the newest assistant text.
function trimFooter(lines) {
  let cut = -1;
  const from = Math.max(0, lines.length - 25);
  for (let i = lines.length - 1; i >= from; i--) {
    const s = lines[i].trim();
    if (!s) continue;
    if (STATUS_BAR.test(s) || CODEX_MODEL_BAR.test(s)) {
      cut = i;
      break;
    }
  }
  if (cut < 0) return { lines, footerFound: false };
  // Also swallow the input box that sits directly above the status bar.
  let end = cut;
  while (end > 0) {
    const s = lines[end - 1].trim();
    if (!s || RULE_ONLY.test(s) || EMPTY_PROMPT.test(s)) {
      end--;
      continue;
    }
    break;
  }
  return { lines: lines.slice(0, end), footerFound: true };
}

// ---------------------------------------------------------------------------
// per-agent profiles
// ---------------------------------------------------------------------------

// A collapsed tool receipt claude prints between messages:
//   "Ran 1 shell command"
//   "Searched for 2 patterns, read 2 files, ran 6 shell commands"
//   "Made 1 scratchpad edit +70, listed 2 directories, ran 7 shell commands"
const RECEIPT_VERB =
  '(?:ran|read|searched|listed|made|wrote|edited|created|deleted|fetched|explored|updated|viewed|launched|killed|added|removed|checked|globbed|grepped|browsed)';
const RECEIPT_CLAUSE = new RegExp(
  `^${RECEIPT_VERB}(?: for| to| up| out| through)? \\d+[\\w+.\\- ]*$`,
  'i'
);
function isToolReceipt(s) {
  if (!/\d/.test(s)) return false;
  if (!/^[A-Z]/.test(s)) return false;
  if (s.length > 160) return false;
  const parts = s.split(/,\s+/);
  for (let i = 0; i < parts.length; i++) {
    if (!RECEIPT_CLAUSE.test(parts[i].trim())) return false;
  }
  return true;
}

// claude renders a tool invocation as "● Verb(argument)" or as a plain-English
// title whose result is nested under a "⎿" elbow.
const CLAUDE_CALL = /^[A-Z][A-Za-z0-9_]*\(/;
const CLAUDE_SYSTEM =
  /^(?:User declined|User rejected|Interrupted by user|API Error|Request interrupted|Compacted|Referenced file|No \(tell Claude|Backgrounded agent|Allowed by auto mode)/;
// A one-line gerund title with no sentence punctuation is a tool label whose
// result has not landed yet ("● Checking script wiring").
const CLAUDE_GERUND_TITLE = /^[A-Z][a-z]+ing\b[^.!?:]*$/;

// codex prints tool calls with the same bullet as prose, so the vocabulary
// matters. Each of these is a rendered tool card or a system notice.
const CODEX_TOOL_HEAD = new RegExp(
  [
    '^Ran\\b',
    '^Explored$',
    '^Explored\\b',
    '^Read (?:\\d+ files?|\\S+)$',
    '^Searched (?:the web|for)\\b',
    '^Listed\\b',
    '^Viewed\\b',
    '^Wrote \\S+$',
    '^Edited \\d+ files?\\b',
    '^Edited \\S+ \\(\\+\\d+',
    '^Applied patch\\b',
    '^Proposed\\b',
    '^Updated Plan$',
    '^Called \\S+\\(',
    '^Waited for\\b',
    '^Waiting for\\b',
    '^Working \\(',
    '^Thinking\\b',
    '^Model changed to\\b',
    '^Context (?:compacted|left)\\b',
    '^Token usage:',
    '^Interacted with background terminal\\b',
  ].join('|')
);

const PROFILES = {
  claude: {
    name: 'claude',
    // "● " in the left gutter. Allow a small indent: herdr re-wraps deep
    // scrollback and can shift the whole frame right by a column or two.
    head: /^([ ]{0,2})●\s(.*)$/,
    user: /^([ ]{0,2})❯(?:\s(.*))?$/,
    // A nested tool result. Its presence anywhere in a block proves the block
    // is a tool card, not a message.
    elbow: /^⎿/,
    turnEnd: /^[✻✳✽]\s|^※\s/,
    isToolHead(s) {
      return CLAUDE_CALL.test(s) || CLAUDE_SYSTEM.test(s);
    },
    isToolTitle(s, bodyLines) {
      return bodyLines.length === 0 && s.length <= 70 && CLAUDE_GERUND_TITLE.test(s);
    },
  },
  codex: {
    name: 'codex',
    head: /^([ ]{0,2})•\s(.*)$/,
    user: /^([ ]{0,2})[›»](?:\s(.*))?$/,
    // "│ " continuation and "└ " result gutters mark a tool card.
    elbow: /^[│└⋮├]/,
    turnEnd: /^─{5,}|^─\s+Worked for\b/,
    isToolHead(s) {
      return CODEX_TOOL_HEAD.test(s);
    },
    isToolTitle() {
      return false;
    },
  },
  opencode: {
    name: 'opencode',
    // opencode has no per-message bullet: the user turn sits inside a "┃"
    // rail and the assistant's prose is a plain indented run underneath.
    head: null,
    user: /^[ ]{0,4}┃/,
    elbow: /^[│└├⎿]/,
    turnEnd: /^[ ]*▣\s/,
    bodyIndent: 5,
    isToolHead(s) {
      return /^(?:▣|◆|◇|⊙|⏺)\s/.test(s) || /^\+\s*Thought:/.test(s);
    },
    isToolTitle() {
      return false;
    },
  },
};

const AGENT_ALIASES = {
  claude: 'claude',
  'claude-code': 'claude',
  claudecode: 'claude',
  cc: 'claude',
  codex: 'codex',
  'openai-codex': 'codex',
  opencode: 'opencode',
  oc: 'opencode',
};

function resolveProfile(agent) {
  if (typeof agent !== 'string') return null;
  const key = AGENT_ALIASES[agent.trim().toLowerCase()];
  return key ? PROFILES[key] : null;
}

// ---------------------------------------------------------------------------
// segmentation
// ---------------------------------------------------------------------------

/**
 * Split normalised lines into blocks. A block starts at a gutter marker in
 * column 0-2 and runs until the next marker; indented and blank lines belong
 * to whatever block is open.
 *
 * @returns {{kind:'assistant'|'tool'|'user'|'chrome', head:string, body:string[], marked:boolean}[]}
 */
function segment(lines, profile) {
  const blocks = [];
  let cur = null;

  const push = () => {
    if (cur) blocks.push(cur);
    cur = null;
  };
  const open = (kind, head, marked, indent) => {
    push();
    cur = { kind, head, body: [], marked, indent };
  };

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const s = raw.trim();
    const ind = indentOf(raw);

    // Chrome never opens or extends a block, with one exception: a turn-end
    // marker closes the block that precedes it.
    if (isChrome(raw)) {
      if (s && cur && profile.turnEnd && profile.turnEnd.test(s)) {
        cur.turnEnded = true;
        push();
      } else if (s && !RULE_ONLY.test(s)) {
        // Real chrome (status bar, recap) also ends whatever came before.
        push();
      } else if (!s && cur) {
        cur.body.push('');
      }
      continue;
    }

    if (profile.user && profile.user.test(raw)) {
      const m = profile.user.exec(raw);
      open('user', (m && m[2]) || '', true, ind);
      continue;
    }

    if (profile.head) {
      const m = profile.head.exec(raw);
      if (m) {
        open('assistant', m[2] || '', true, m[1].length);
        continue;
      }
    }

    // A structurally indented line continues the open block.
    if (cur && (ind > cur.indent || (profile.head === null && ind >= (profile.bodyIndent || 2)))) {
      cur.body.push(raw);
      continue;
    }
    if (cur && ind >= 2 && ind > cur.indent - 1 && profile.head) {
      cur.body.push(raw);
      continue;
    }

    // Column-0 text with no marker. For markerless layouts (opencode) that
    // means chrome; elsewhere it is a wrapped continuation of a notice.
    if (profile.head === null && ind >= (profile.bodyIndent || 5)) {
      if (!cur || cur.kind !== 'assistant') open('assistant', raw.trim(), false, ind);
      else cur.body.push(raw);
      continue;
    }
    if (cur) {
      cur.body.push(raw);
      continue;
    }
    // Nothing open: this is the top of the capture window, mid-message.
    open('assistant', s, false, ind);
  }
  push();

  // Classify.
  for (let i = 0; i < blocks.length; i++) {
    const b = blocks[i];
    if (b.kind !== 'assistant') continue;
    const bodyText = b.body.filter((l) => l.trim());
    const hasElbow = bodyText.some((l) => profile.elbow && profile.elbow.test(l.trim()));
    if (hasElbow || profile.isToolHead(b.head) || profile.isToolTitle(b.head, bodyText)) {
      b.kind = 'tool';
    }
  }
  return blocks;
}

// ---------------------------------------------------------------------------
// rendering
// ---------------------------------------------------------------------------

const LIST_MARKER = /^(?:[-*+•▪◦·]\s|\d+[.)]\s|#{1,6}\s|>\s|\|.*\||```|⎮)/;
const QUOTE_RAIL = /^▎\s?/; // claude renders markdown blockquotes with "▎"

// Lines that are tool debris even inside an otherwise prose block.
function isBlockNoise(s, profile) {
  if (!s) return false;
  if (profile.elbow && profile.elbow.test(s)) return true;
  if (TRUNCATION.test(s)) return true;
  if (isToolReceipt(s)) return true;
  if (/^\$\s/.test(s)) return true; // echoed shell command
  if (/^⋮$/.test(s)) return true; // diff gap marker
  if (/^\d+\s+[+-]\s/.test(s)) return true; // numbered diff row
  if (/^[◼◻■□]\s/.test(s)) return true; // todo checkboxes
  return false;
}

/**
 * Undo the terminal's hard wrapping and emit markdown.
 *
 * The terminal wraps at a fixed width, so a line that reaches (near) that width
 * was almost certainly continued on the next line. Short lines ended on their
 * own. List/heading/quote markers always start a fresh line regardless.
 */
function renderBlock(block, profile, wrapWidth) {
  const raw = [block.head === undefined ? '' : block.head].concat(block.body);
  // The head arrives already stripped of its bullet, so give it the same
  // effective indent as the body for the de-wrap comparison.
  const headIndent = block.indent + 2;

  const kept = [];
  for (let i = 0; i < raw.length; i++) {
    const line = i === 0 ? ' '.repeat(headIndent) + raw[0] : raw[i];
    const s = line.trim();
    if (!s) {
      kept.push(null); // paragraph break
      continue;
    }
    if (isChrome(line) || isBlockNoise(s, profile)) continue;
    kept.push({ indent: indentOf(line), text: s });
  }
  while (kept.length && kept[0] === null) kept.shift();
  while (kept.length && kept[kept.length - 1] === null) kept.pop();
  if (!kept.length) return '';

  // Normalise to the block's own left margin so nested markdown survives.
  let base = Infinity;
  for (const k of kept) if (k && k.indent < base) base = k.indent;
  if (!isFinite(base)) base = 0;

  const threshold = Math.max(40, wrapWidth - 14);
  const out = [];
  let buf = null;
  let bufIndent = 0;
  let prevLen = 0;

  const flush = () => {
    if (buf !== null) out.push(' '.repeat(bufIndent) + buf);
    buf = null;
  };

  for (let i = 0; i < kept.length; i++) {
    const k = kept[i];
    if (k === null) {
      flush();
      if (out.length && out[out.length - 1] !== '') out.push('');
      prevLen = 0;
      continue;
    }
    const rel = Math.max(0, k.indent - base);
    let text = k.text;
    let quoted = false;
    if (QUOTE_RAIL.test(text)) {
      text = '> ' + text.replace(QUOTE_RAIL, '');
      quoted = true;
    }
    const startsNew =
      buf === null ||
      quoted ||
      LIST_MARKER.test(text) ||
      prevLen < threshold ||
      rel > bufIndent + 3;

    if (startsNew) {
      flush();
      buf = text;
      bufIndent = rel;
    } else {
      // Paths and hyphenates wrap mid-token; rejoin those without a space.
      buf += /[/\-—]$/.test(buf) ? text : ' ' + text;
    }
    prevLen = k.indent + k.text.length;
  }
  flush();

  return out
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// ---------------------------------------------------------------------------
// analysis
// ---------------------------------------------------------------------------

// A block has to look like a sentence, not a widget label, to count as prose.
function looksLikeProse(text) {
  if (!text) return false;
  const t = text.trim();
  if (t.length < 8) return false;
  if (t.split(/\s+/).length < 2) return false;
  return true;
}

function wrapWidthOf(lines) {
  let w = 0;
  for (let i = 0; i < lines.length; i++) if (lines[i].length > w) w = lines[i].length;
  return w || 100;
}

// Whole-capture guard: herdr hands back a JSON error object when a pane cannot
// be read. That is not a transcript.
function isHerdrError(lines) {
  const solid = lines.filter((l) => l.trim());
  if (solid.length !== 1) return false;
  const s = solid[0].trim();
  if (!s.startsWith('{') || !s.endsWith('}')) return false;
  try {
    const o = JSON.parse(s);
    return !!(o && (o.error || o.id));
  } catch {
    return false;
  }
}

// Shared front half of every read: normalise the capture, pick the layout that
// explains it best, and split it into blocks. Returns null when the text is not
// a transcript at all.
function prepare(text, opts) {
  let lines = toLines(text);
  if (!lines.length || !lines.some((l) => l.trim())) return null;
  if (isHerdrError(lines)) return null;

  const wrapWidth = wrapWidthOf(lines);
  const trimmed = trimFooter(lines);
  lines = trimmed.lines;
  if (!lines.length) return null;

  const explicit = resolveProfile(opts && opts.agent);
  const candidates = explicit
    ? [explicit]
    : [PROFILES.claude, PROFILES.codex, PROFILES.opencode];

  let best = null;
  for (const profile of candidates) {
    const blocks = segment(lines, profile);
    let marked = 0;
    let prose = 0;
    for (const b of blocks) {
      if (b.marked && (b.kind === 'assistant' || b.kind === 'tool' || b.kind === 'user')) marked++;
      if (b.kind === 'assistant') prose++;
    }
    const score = marked * 2 + prose;
    if (!best || score > best.score) best = { profile, blocks, score, prose };
  }
  if (!best) return null;
  return { ...best, lines, wrapWidth, explicit };
}

function analyse(text, opts) {
  const empty = { answer: '', confidence: 'low', kind: 'unknown', profile: 'none' };
  const prep = prepare(text, opts);
  if (!prep) return empty;
  const { lines, wrapWidth, explicit } = prep;
  const best = prep;

  if (!explicit && best.score === 0) {
    const loose = looseFallback(lines, wrapWidth);
    return loose || empty;
  }

  const { profile, blocks } = best;

  // Walk back for the newest assistant block that renders to real prose.
  let idx = -1;
  let answer = '';
  for (let i = blocks.length - 1; i >= 0; i--) {
    if (blocks[i].kind !== 'assistant') continue;
    const rendered = renderBlock(blocks[i], profile, wrapWidth);
    if (looksLikeProse(rendered)) {
      idx = i;
      answer = rendered;
      break;
    }
  }

  if (idx < 0) {
    const sawTool = blocks.some((b) => b.kind === 'tool');
    const loose = looseFallback(lines, wrapWidth);
    if (loose && loose.answer) return { ...loose, profile: profile.name };
    return {
      answer: '',
      confidence: 'low',
      kind: sawTool ? 'tool' : 'unknown',
      profile: profile.name,
    };
  }

  // Confidence: the turn has to be over and this has to be the last thing the
  // agent said. A tool card after it means the model is still mid-turn, and an
  // unmarked block means the capture window cut the message's opening off.
  let toolAfter = false;
  for (let i = idx + 1; i < blocks.length; i++) {
    if (blocks[i].kind === 'tool' || blocks[i].kind === 'assistant') toolAfter = true;
  }
  // A live frame always has a footer, including while the model is still
  // working. Only an explicit turn-end marker proves this is its final reply.
  const turnEnded = !!blocks[idx].turnEnded;
  const confidence =
    blocks[idx].marked && !toolAfter && turnEnded && answer.length >= 20 ? 'high' : 'low';

  return { answer, confidence, kind: 'prose', profile: profile.name, blocks, idx };
}

// Last resort for layouts we do not recognise: strip chrome, throw away
// anything that smells like tool output, and keep the final run of sentences.
function looseFallback(lines, wrapWidth) {
  const cleaned = [];
  for (const raw of lines) {
    const s = raw.trim();
    if (isChrome(raw)) {
      cleaned.push('');
      continue;
    }
    if (
      isBlockNoise(s, PROFILES.codex) ||
      /^[●•]?\s*(?:Ran|Read|Explored|Searched|Listed|Edited|Wrote|Called|Viewed|Applied patch|Updated Plan)\b/.test(
        s
      ) ||
      /^[+-]{1,3}\s|^@@ /.test(s) ||
      /^\s*\d+\s*[+|]/.test(raw)
    ) {
      cleaned.push('');
      continue;
    }
    cleaned.push(raw.replace(/^([ ]{0,2})[●•]\s/, '$1  '));
  }

  // Take the last contiguous run of non-blank lines that reads like sentences.
  let end = cleaned.length;
  while (end > 0 && !cleaned[end - 1].trim()) end--;
  if (!end) return null;
  let start = end;
  while (start > 0 && cleaned[start - 1].trim()) start--;

  const block = { head: undefined, body: cleaned.slice(start, end), indent: 0 };
  const answer = renderBlock(block, PROFILES.codex, wrapWidth);
  if (!looksLikeProse(answer)) return null;
  const words = answer.split(/\s+/).length;
  if (words < 4) return null;
  return { answer, confidence: 'low', kind: 'prose', profile: 'generic' };
}

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

/**
 * Extract the human-facing reply from a captured agent terminal.
 *
 * @param {string} text  raw pane text (ANSI tolerated)
 * @param {{agent?: string}} [opts]
 * @returns {{answer: string, confidence: 'high'|'low', kind: 'prose'|'tool'|'unknown'}}
 *   `answer` is markdown-ready prose, '' when nothing prose-like was found.
 *   `kind` is 'prose' when an answer was recovered, 'tool' when the newest
 *   activity is a tool card with no readable prose behind it, 'unknown'
 *   otherwise. `confidence` is 'high' only when the recovered text is a
 *   complete, finished, most-recent assistant message.
 */
function extractAnswer(text, opts) {
  try {
    const r = analyse(text, opts || {});
    return { answer: r.answer || '', confidence: r.confidence, kind: r.kind };
  } catch {
    return { answer: '', confidence: 'low', kind: 'unknown' };
  }
}

/**
 * The most recent assistant turn, as plain markdown. Same extraction as
 * `extractAnswer` without the confidence signalling.
 *
 * @param {string} text
 * @param {{agent?: string}} [opts]
 * @returns {string}
 */
function lastAssistantBlock(text, opts) {
  try {
    const r = analyse(text, opts || {});
    return r.answer || '';
  } catch {
    return '';
  }
}

const TOOL_LABEL_MAX = 90;

// A tool card, reduced to the one line a human would read: "Ran npm test",
// "Read(src/index.js)". The body is the tool's own output and belongs in the
// raw transcript, not in a narration.
function toolLabel(block) {
  let head = String(block.head === undefined ? '' : block.head).trim();
  if (!head) {
    head = (block.body || []).map((s) => String(s).trim()).find(Boolean) || '';
  }
  head = head.replace(/\s+/g, ' ');
  if (!head) return '';
  return head.length > TOOL_LABEL_MAX ? `${head.slice(0, TOOL_LABEL_MAX - 1)}…` : head;
}

/**
 * Everything the agent has said and done in this capture, in order — the
 * running commentary behind a turn rather than only its conclusion.
 *
 * The last item is flagged: mid-turn it is very likely still being written, so
 * a caller streaming these should hold it back until something follows it.
 *
 * @param {string} text  raw pane text (ANSI tolerated)
 * @param {{agent?: string}} [opts]
 * @returns {{items: {kind:'assistant'|'tool', text:string, last:boolean}[], profile:string}}
 */
function narrate(text, opts) {
  try {
    const prep = prepare(text, opts || {});
    if (!prep || !prep.blocks) return { items: [], profile: 'none' };
    const { profile, blocks, wrapWidth } = prep;

    const items = [];
    for (const b of blocks) {
      if (b.kind === 'assistant') {
        // The window starts mid-block when the top has scrolled away, and what
        // is left carries no marker to say whose words they were. Often they
        // are the human's own prompt, wrapped and indented exactly like a
        // reply. Never open a narration with one.
        if (!items.length && !b.marked) continue;
        const rendered = renderBlock(b, profile, wrapWidth);
        if (looksLikeProse(rendered)) items.push({ kind: 'assistant', text: rendered, last: false });
        // Newer claude builds do not draw a card per call: they fold the work
        // into a receipt line inside the message ("Read 1 file", "Made 3 edits
        // +6"). renderBlock drops those as debris, which is right for an
        // answer and wrong for a narration — it is the only evidence of what
        // the agent did. They sit after the prose they follow, so emit them
        // in that order.
        for (const raw of b.body || []) {
          const s = String(raw).trim();
          if (s && isToolReceipt(s)) items.push({ kind: 'tool', text: s, last: false });
        }
      } else if (b.kind === 'tool') {
        const label = toolLabel(b);
        if (label) items.push({ kind: 'tool', text: label, last: false });
      } else if (b.kind === 'user') {
        // Not for posting — the prompt is already in the thread — but a caller
        // catching up mid-run needs to know where the current turn began.
        const asked = renderBlock(b, profile, wrapWidth);
        if (asked) items.push({ kind: 'user', text: asked, last: false });
      }
    }
    if (items.length) items[items.length - 1].last = true;
    return { items, profile: profile.name };
  } catch {
    return { items: [], profile: 'none' };
  }
}

module.exports = {
  extractAnswer,
  lastAssistantBlock,
  narrate,
  stripChrome,
  isChrome,
  // exported for tests / callers that want to reuse the primitives
  stripAnsi,
  toLines,
};

// Real-time herdr event source.
//
// herdr's socket API (protocol 19) exposes a native subscription mechanism:
//
//   method: "events.subscribe"
//   params: { subscriptions: [ { type: "pane.updated" }, ... ] }
//
// The transport is newline-delimited JSON over the unix socket at
// ~/.config/herdr/herdr.sock. A connection that issues `events.subscribe`
// becomes a *dedicated* event stream: the server answers once with
// {"result":{"type":"subscription_started"}} and then pushes event envelopes
// forever. Sending any other request on that same connection makes the server
// drop it, so this module keeps the stream socket for nothing else.
//
// Event envelopes look like:
//   {"event":"pane_updated","data":{"type":"pane_updated","pane":{...PaneInfo}}}
// PaneInfo carries agent, agent_status, cwd, terminal_title*, workspace_id,
// tab_id and a monotonic `revision` that bumps whenever new terminal output is
// rendered — so one global `pane.updated` subscription covers both "an agent
// changed state" and "new output appeared".
//
// A `herdr agent list` poll is kept as a fallback (used when the socket is
// unavailable) and as a slow reconcile while the stream is live.
//
// Everything shells out via execFile with an argv array — no shell string is
// ever constructed, so nothing here is injectable.

const { EventEmitter } = require('node:events');
const { execFile } = require('node:child_process');
const net = require('node:net');
const os = require('node:os');
const path = require('node:path');

const HERDR_BIN = process.env.HERDR_BIN || 'herdr';
const EXEC_TIMEOUT_MS = Number(process.env.HERDR_TIMEOUT_MS || 15000);

// Global (no pane_id required) subscriptions that together describe the agent
// population and its state. `pane.agent_status_changed` and
// `pane.output_matched` exist too but both require a concrete pane_id, so they
// are unusable for watching every agent at once.
const STREAM_SUBSCRIPTIONS = [
  { type: 'pane.created' },
  { type: 'pane.updated' },
  { type: 'pane.closed' },
  { type: 'pane.exited' },
  { type: 'pane.agent_detected' },
];

const MAX_STREAM_BUFFER = 4 * 1024 * 1024;

function defaultSocketPath() {
  if (process.env.HERDR_SOCK) return process.env.HERDR_SOCK;
  if (process.env.HERDR_SOCKET) return process.env.HERDR_SOCKET;
  const cfgHome =
    process.env.XDG_CONFIG_HOME || path.join(os.homedir(), '.config');
  return path.join(cfgHome, 'herdr', 'herdr.sock');
}

// Same field names as src/herdr.js `normalizeAgent`, plus `revision` (used to
// detect new terminal output).
function normalizeAgent(a) {
  return {
    paneId: a.pane_id,
    agent: a.agent,
    status: a.agent_status,
    cwd: a.cwd,
    title: a.terminal_title_stripped || a.terminal_title || '',
    focused: !!a.focused,
    workspaceId: a.workspace_id,
    tabId: a.tab_id,
    sessionValue: a.agent_session?.value,
    revision: a.revision,
  };
}

function runHerdrJson(args) {
  return new Promise((resolve, reject) => {
    execFile(
      HERDR_BIN,
      args,
      { timeout: EXEC_TIMEOUT_MS, maxBuffer: 8 * 1024 * 1024 },
      (err, stdout, stderr) => {
        if (err) {
          const msg = (stderr && String(stderr).trim()) || err.message;
          reject(new Error(`herdr ${args.join(' ')} failed: ${msg}`));
          return;
        }
        const trimmed = String(stdout).trim();
        if (!trimmed) {
          resolve({});
          return;
        }
        try {
          resolve(JSON.parse(trimmed));
        } catch {
          reject(new Error(`herdr ${args.join(' ')} returned non-JSON output`));
        }
      },
    );
  });
}

/**
 * @param {object} [opts]
 * @param {number} [opts.pollMs=4000]      Poll interval while the stream is down.
 * @param {number} [opts.reconcileMs=30000] Slow reconcile poll while streaming.
 * @param {number} [opts.outputThrottleMs=1000] Min gap between `agent-output`
 *   emissions for a single pane. 0 disables throttling.
 * @param {boolean} [opts.emitInitial=false] Emit `agent-added` for agents that
 *   already exist at start().
 * @param {boolean} [opts.useStream=true]  Set false to force polling only.
 * @param {number} [opts.readyTimeoutMs=2000] How long start() waits for the
 *   subscription handshake before resolving anyway.
 * @param {string}  [opts.socketPath]      Override the herdr socket path.
 *
 * @returns {EventEmitter & {start:Function, stop:Function, getAgents:Function, isStreaming:Function}}
 *
 * Events:
 *   'ready'         { agents, streaming }        once, after the first snapshot
 *   'agent-added'   agent
 *   'agent-removed' agent
 *   'agent-status'  { ...agent, prevStatus }
 *   'agent-output'  { ...agent, prevRevision }   new terminal output rendered
 *   'stream-open'   { socketPath }
 *   'stream-closed' { reason }
 *   'error'         Error
 */
function createHerdrEvents(opts = {}) {
  const {
    pollMs = 4000,
    reconcileMs = 30000,
    outputThrottleMs = 1000,
    emitInitial = false,
    useStream = true,
    readyTimeoutMs = 2000,
    socketPath = defaultSocketPath(),
  } = opts;

  const emitter = new EventEmitter();

  /** @type {Map<string, ReturnType<typeof normalizeAgent>>} */
  const agents = new Map();
  /** @type {Map<string, number>} */
  const lastOutputAt = new Map();

  let running = false;
  let primed = false;
  let streaming = false;
  let sock = null;
  let sockBuf = '';
  let pollTimer = null;
  let reconnectTimer = null;
  let reconnectAttempt = 0;
  let pollInFlight = false;
  let readySettle = null;

  // Resolves once the first subscribe attempt has either succeeded or failed,
  // so the 'ready' payload reports the real transport.
  function settleReady() {
    if (!readySettle) return;
    const fn = readySettle;
    readySettle = null;
    fn();
  }

  function emitError(err) {
    const e = err instanceof Error ? err : new Error(String(err));
    // A stray 'error' with no listener would throw and kill the host process,
    // which is the wrong failure mode for a long-running bot.
    if (emitter.listenerCount('error') > 0) emitter.emit('error', e);
    else console.error('[herdr-events]', e.message);
  }

  // ---- diffing ------------------------------------------------------------

  function emitOutput(next, prevRevision) {
    if (!primed) return;
    if (outputThrottleMs > 0) {
      const now = Date.now();
      const last = lastOutputAt.get(next.paneId) || 0;
      if (now - last < outputThrottleMs) return;
      lastOutputAt.set(next.paneId, now);
    }
    emitter.emit('agent-output', { ...next, prevRevision });
  }

  // Apply one pane's state. Panes without a recognized agent are treated as
  // "not an agent" and drop out of the set.
  function applyPane(raw) {
    if (!raw || !raw.pane_id) return;
    const next = normalizeAgent(raw);
    const prev = agents.get(next.paneId);

    if (!next.agent) {
      if (prev) {
        agents.delete(next.paneId);
        lastOutputAt.delete(next.paneId);
        if (primed) emitter.emit('agent-removed', prev);
      }
      return;
    }

    agents.set(next.paneId, next);

    if (!prev) {
      if (primed || emitInitial) emitter.emit('agent-added', next);
      return;
    }
    if (prev.status !== next.status) {
      emitter.emit('agent-status', { ...next, prevStatus: prev.status });
    }
    if (
      typeof next.revision === 'number' &&
      typeof prev.revision === 'number' &&
      next.revision > prev.revision
    ) {
      emitOutput(next, prev.revision);
    }
  }

  function removePane(paneId) {
    const prev = agents.get(paneId);
    if (!prev) return;
    agents.delete(paneId);
    lastOutputAt.delete(paneId);
    if (primed) emitter.emit('agent-removed', prev);
  }

  // Apply an authoritative full list (`herdr agent list`).
  function applyFullList(list) {
    const seen = new Set();
    for (const raw of list) {
      seen.add(raw.pane_id);
      applyPane(raw);
    }
    for (const paneId of [...agents.keys()]) {
      if (!seen.has(paneId)) removePane(paneId);
    }
  }

  async function snapshot() {
    const data = await runHerdrJson(['agent', 'list']);
    return data?.result?.agents || [];
  }

  // ---- polling ------------------------------------------------------------

  function schedulePoll() {
    if (!running) return;
    clearTimeout(pollTimer);
    const delay = streaming ? reconcileMs : pollMs;
    if (!Number.isFinite(delay) || delay <= 0) return;
    pollTimer = setTimeout(pollOnce, delay);
  }

  async function pollOnce() {
    if (!running || pollInFlight) return;
    pollInFlight = true;
    try {
      applyFullList(await snapshot());
    } catch (err) {
      emitError(err);
    } finally {
      pollInFlight = false;
      schedulePoll();
    }
  }

  // ---- stream -------------------------------------------------------------

  function handleEnvelope(msg) {
    if (msg.error) {
      emitError(new Error(`herdr events.subscribe: ${msg.error.message}`));
      return;
    }
    if (msg.id !== undefined && msg.result) {
      if (msg.result.type === 'subscription_started') {
        streaming = true;
        reconnectAttempt = 0;
        settleReady();
        emitter.emit('stream-open', { socketPath });
        // Close the gap between the priming snapshot and the first event.
        pollOnce();
      }
      return;
    }

    const data = msg.data;
    if (!data) return;
    switch (msg.event) {
      case 'pane_created':
      case 'pane_updated':
        applyPane(data.pane);
        break;
      case 'pane_closed':
      case 'pane_exited':
        removePane(data.pane_id);
        break;
      case 'pane_agent_detected':
        // Carries no PaneInfo; `released: true` means the agent went away.
        if (data.released) removePane(data.pane_id);
        break;
      default:
        break;
    }
  }

  function teardownSocket() {
    if (!sock) return;
    const s = sock;
    sock = null;
    sockBuf = '';
    s.removeAllListeners();
    s.destroy();
  }

  function onStreamDown(reason) {
    if (!running) return;
    const wasStreaming = streaming;
    streaming = false;
    teardownSocket();
    settleReady();
    if (wasStreaming) emitter.emit('stream-closed', { reason });
    schedulePoll(); // fall back to the fast poll interval
    scheduleReconnect();
  }

  function scheduleReconnect() {
    if (!running || reconnectTimer) return;
    const delay = Math.min(1000 * 2 ** reconnectAttempt, 30000);
    reconnectAttempt += 1;
    reconnectTimer = setTimeout(() => {
      reconnectTimer = null;
      connectStream();
    }, delay);
  }

  function connectStream() {
    if (!running || sock) return;
    let s;
    try {
      s = net.createConnection({ path: socketPath });
    } catch (err) {
      emitError(err);
      scheduleReconnect();
      return;
    }
    sock = s;
    sockBuf = '';
    s.setEncoding('utf8');

    s.on('connect', () => {
      if (sock !== s) return;
      try {
        s.setNoDelay(true);
      } catch {
        /* not a TCP socket; ignore */
      }
      // Exactly one request on this connection, ever.
      s.write(
        `${JSON.stringify({
          id: 'herdr-events:subscribe',
          method: 'events.subscribe',
          params: { subscriptions: STREAM_SUBSCRIPTIONS },
        })}\n`,
      );
    });

    s.on('data', (chunk) => {
      if (sock !== s) return;
      sockBuf += chunk;
      if (sockBuf.length > MAX_STREAM_BUFFER) {
        sockBuf = '';
        emitError(new Error('herdr event stream buffer overflow; resetting'));
        onStreamDown('overflow');
        return;
      }
      let nl;
      while ((nl = sockBuf.indexOf('\n')) !== -1) {
        const line = sockBuf.slice(0, nl).trim();
        sockBuf = sockBuf.slice(nl + 1);
        if (!line) continue;
        let msg;
        try {
          msg = JSON.parse(line);
        } catch {
          emitError(new Error('herdr event stream sent unparseable JSON'));
          continue;
        }
        try {
          handleEnvelope(msg);
        } catch (err) {
          emitError(err);
        }
      }
    });

    s.on('error', (err) => {
      if (sock !== s) return;
      if (streaming || reconnectAttempt === 0) emitError(err);
      onStreamDown(err.message);
    });

    s.on('close', () => {
      if (sock !== s) return;
      onStreamDown('closed');
    });
  }

  // ---- lifecycle ----------------------------------------------------------

  async function start() {
    if (running) return emitter;
    running = true;
    reconnectAttempt = 0;

    try {
      applyFullList(await snapshot());
    } catch (err) {
      emitError(err);
    }
    if (!running) return emitter;
    primed = true;

    if (useStream) {
      await new Promise((resolve) => {
        const timer = setTimeout(settleReady, readyTimeoutMs);
        readySettle = () => {
          clearTimeout(timer);
          resolve();
        };
        connectStream();
      });
      if (!running) return emitter;
    }
    schedulePoll();
    emitter.emit('ready', { agents: [...agents.values()], streaming });
    return emitter;
  }

  function stop() {
    running = false;
    streaming = false;
    primed = false;
    clearTimeout(pollTimer);
    clearTimeout(reconnectTimer);
    pollTimer = null;
    reconnectTimer = null;
    teardownSocket();
    settleReady();
    agents.clear();
    lastOutputAt.clear();
  }

  emitter.start = start;
  emitter.stop = stop;
  emitter.getAgents = () => [...agents.values()];
  emitter.isStreaming = () => streaming;
  emitter.socketPath = socketPath;

  return emitter;
}

module.exports = { createHerdrEvents, normalizeAgent };
